insert into public.therapist_resources (slug, title, kind, summary, goal, audience, duration, body_md, fields, tags, created_at)
values
  ('hands-as-thoughts-exercise', 'Hands as Thoughts Exercise', 'act'::resource_kind, 'A hands-on defusion demonstration where thoughts are held up close, then held out at a distance.', 'Let the client feel the difference between being fused with a thought and holding it.', array['Adults', 'Teens']::text[], '15 minutes', 'Ask the client to cup their hands over their face and describe how the room looks, then lower them to the lap and describe it again. Let them pick a sticky thought to hold in their hands. The point is not to make the thought vanish but to notice what changes in how much it steers behavior. Go slowly, and check in about what they noticed in the body.', '[{"id": "f0", "type": "textarea", "label": "The thought I chose to hold in my hands"}, {"id": "f1", "type": "textarea", "label": "What I could see and do with my hands over my face"}, {"id": "f2", "type": "textarea", "label": "What shifted when I held my hands out or lowered them"}, {"id": "f3", "type": "textarea", "label": "What the thought still said, and how much it ran things"}, {"id": "f4", "type": "textarea", "label": "One moment this week I could try holding a thought this way"}]'::jsonb, array['defusion', 'metaphor', 'core ACT']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('hooked-and-unhooked-tracker', 'Hooked and Unhooked Tracker', 'act'::resource_kind, 'A short daily log of moments when a thought or feeling pulled the client off course, and what helped them step back.', 'Help the client spot hooks sooner and name what unhooking looks like for them.', array['Adults', 'Teens']::text[], 'Five minutes daily for one week', 'Introduce being hooked as an ordinary experience rather than a fault, and have the client log two or three moments a day. Look through the log together for patterns in hooks, such as people, places or times of day. Notice which small unhooking moves worked and build on those instead of asking for a perfect week.', '[{"id": "f0", "type": "textarea", "label": "The moment I got hooked"}, {"id": "f1", "type": "textarea", "label": "What my mind said or what I felt in my body"}, {"id": "f2", "type": "textarea", "label": "What I did while hooked"}, {"id": "f3", "type": "textarea", "label": "What I noticed when I started to unhook"}, {"id": "f4", "type": "textarea", "label": "What I did next that moved me toward something I care about"}, {"id": "f5", "type": "textarea", "label": "What I want to remember for next time"}]'::jsonb, array['defusion', 'behavior', 'willingness']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('values-versus-goals-sort', 'Values Versus Goals Sort', 'act'::resource_kind, 'A card or list sort that separates directions the client values from goals that can be checked off.', 'Clarify the difference between a direction to live by and an outcome to reach.', array['Adults', 'Teens']::text[], '25 minutes', 'Have the client list several things they are working toward, then sort each into a goal, which can be finished, or a value, which is a way of moving that never ends. Many clients discover a goal sitting on top of a value they had not named. Ask what the goal is in service of, and let them find the words themselves rather than supplying yours.', '[{"id": "f0", "type": "textarea", "label": "A goal I am working toward right now"}, {"id": "f1", "type": "textarea", "label": "Why it matters to me, and what it is in service of"}, {"id": "f2", "type": "textarea", "label": "The value underneath it, in my own words"}, {"id": "f3", "type": "textarea", "label": "A goal I have already reached that still left me wanting something"}, {"id": "f4", "type": "textarea", "label": "One small way to live this value today whether or not the goal happens"}, {"id": "f5", "type": "textarea", "label": "What gets in the way of that, and what I would be willing to carry along"}]'::jsonb, array['values', 'clarification', 'committed action']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('five-senses-landing-practice', 'Five Senses Landing Practice', 'act'::resource_kind, 'A brief present-moment exercise that moves attention through sight, sound, touch, smell and taste.', 'Give the client a portable way to come back to the present when thoughts pull them away.', array['Adults', 'Teens', 'Groups']::text[], 'Five minutes', 'Walk the client through noticing something with each sense, naming each aloud, and then ask what they notice about where their mind went. Keep it light and optional, and let them skip any sense that feels unpleasant. Frame it as contacting the present rather than clearing the mind, and invite them to practice it in an ordinary moment before they need it in a hard one.', '[{"id": "f0", "type": "textarea", "label": "Something I can see right now"}, {"id": "f1", "type": "textarea", "label": "Something I can hear"}, {"id": "f2", "type": "textarea", "label": "Something I can feel touching my body"}, {"id": "f3", "type": "textarea", "label": "Something I can smell or taste"}, {"id": "f4", "type": "textarea", "label": "Where my mind went while I was noticing"}, {"id": "f5", "type": "textarea", "label": "A time this week I could try landing like this"}]'::jsonb, array['mindfulness', 'present moment', 'grounding']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('obstacle-rehearsal-sheet', 'Obstacle Rehearsal Sheet', 'act'::resource_kind, 'A planning page that names the thoughts and feelings likely to show up and pairs each with a willing response.', 'Prepare the client for inner obstacles before they meet them on the way to a chosen action.', array['Adults', 'Teens']::text[], '20 minutes', 'Choose one small committed action with the client and ask what their mind will predict will go wrong. Write the likely thoughts, feelings and urges, then plan a willing response to each. Rehearse aloud in session if time allows. Keep the action small enough that the client can succeed, and read any miss as information about the plan rather than a failure.', '[{"id": "f0", "type": "textarea", "label": "The action I plan to take and when"}, {"id": "f1", "type": "textarea", "label": "The thoughts my mind is likely to offer"}, {"id": "f2", "type": "textarea", "label": "The feelings or body sensations I expect"}, {"id": "f3", "type": "textarea", "label": "The urge I may feel to put it off or stop"}, {"id": "f4", "type": "textarea", "label": "What I am willing to carry with me while I do it"}, {"id": "f5", "type": "textarea", "label": "How I will know I took the step, however small"}]'::jsonb, array['committed action', 'willingness', 'barriers']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('double-standard-technique-sheet', 'Double Standard Technique Sheet', 'cbt'::resource_kind, 'A two-column sheet comparing what a client tells themselves with what they would tell a friend in the same spot.', 'Use it to help a client notice a harsher inner rule and try a fairer one.', array['Adults', 'Teens']::text[], '20 minutes', 'Pick a recent moment where your client was hard on themselves. Have them fill the friend column first, since kind words come more easily there, then the self column. Watch for answers like ''but I''m different''; ask what makes the rule apply to one person and not the other. The aim is a fairer sentence they can try, not forced self-praise.', '[{"id": "f0", "type": "textarea", "label": "The situation and what I told myself about it."}, {"id": "f1", "type": "textarea", "label": "What I would say to a friend who was in exactly the same situation."}, {"id": "f2", "type": "textarea", "label": "Words and tone I used with myself versus with the friend."}, {"id": "f3", "type": "textarea", "label": "Reasons I give for why the rule is different for me."}, {"id": "f4", "type": "textarea", "label": "Does each reason hold up when I look at it closely?"}, {"id": "f5", "type": "textarea", "label": "A fairer sentence I could try saying to myself this week."}]'::jsonb, array['core CBT', 'self-talk', 'thinking traps']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('graded-task-ladder', 'Graded Task Ladder', 'cbt'::resource_kind, 'A ladder that breaks a task a client keeps avoiding into small rungs, each with a predicted difficulty and an actual one.', 'Use it to turn an overwhelming task into steps a client can start this week.', array['Adults', 'Teens']::text[], 'Full session', 'Choose one task your client has been putting off and agree on the top rung together. Work backward until the bottom rung feels doable in a few minutes. Ask for a difficulty guess before each rung and a rating afterward; the gap is often useful. Stay on a rung until it feels manageable rather than hurrying upward, and make sure rungs are about doing, not about how it feels.', '[{"id": "f0", "type": "textarea", "label": "The task I keep putting off."}, {"id": "f1", "type": "textarea", "label": "Why it feels too big, in my own words."}, {"id": "f2", "type": "textarea", "label": "My top rung: the task as I would like to finish it."}, {"id": "f3", "type": "textarea", "label": "The bottom rung: something I could do in under five minutes."}, {"id": "f4", "type": "textarea", "label": "Rungs in between, from easiest to hardest."}, {"id": "f5", "type": "textarea", "label": "Predicted difficulty (0 to 10) before each rung."}, {"id": "f6", "type": "textarea", "label": "Actual difficulty after trying it."}, {"id": "f7", "type": "textarea", "label": "What I noticed about the gap between the two."}]'::jsonb, array['activity scheduling', 'planning', 'core CBT']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('beliefs-about-worry-sheet', 'Beliefs About Worry Sheet', 'cbt'::resource_kind, 'A sheet that explores what a client believes worrying does for them and what it costs, separate from what they worry about.', 'Use it to open up a client''s beliefs about worry itself before changing how they respond.', array['Adults']::text[], '30 minutes', 'Many clients defend worry as protective (''if I stop, something will slip''). Rather than argue, get curious about the belief and ask them to list what worry seems to do and what it costs. Notice any belief that worry is uncontrollable or harmful in itself. A small experiment on one belief can follow, chosen by the client. Keep it exploratory.', '[{"id": "f0", "type": "textarea", "label": "A recent worry and how long it stayed with me."}, {"id": "f1", "type": "textarea", "label": "What I believe worrying does for me."}, {"id": "f2", "type": "textarea", "label": "What I believe would happen if I worried less."}, {"id": "f3", "type": "textarea", "label": "What worrying has cost me in time, energy or relationships."}, {"id": "f4", "type": "textarea", "label": "Times I did not worry and things still went fine."}, {"id": "f5", "type": "textarea", "label": "A small experiment I could try on one of these beliefs."}]'::jsonb, array['worry', 'belief change', 'metacognition']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('perfectionism-standards-experiment', 'Perfectionism Standards Experiment', 'cbt'::resource_kind, 'A planned test where a client does one task to a deliberately looser standard and compares the real outcome with the prediction.', 'Use it to test whether a rigid standard is needed to get acceptable results.', array['Adults', 'Teens']::text[], 'Full session, then one week', 'Choose a low-stakes task where your client over-checks or over-polishes. Name the current standard, then set a looser one with a clear time limit. Record predictions about other people''s reactions and about how they will feel, then compare. Expect discomfort; that is part of the data. Revisit what the extra effort actually bought, and let the client decide which standards stay.', '[{"id": "f0", "type": "textarea", "label": "The task and the standard I usually hold myself to."}, {"id": "f1", "type": "textarea", "label": "What I do to meet that standard, and how much time it takes."}, {"id": "f2", "type": "textarea", "label": "The looser standard I will try, with a time limit."}, {"id": "f3", "type": "textarea", "label": "What I predict will happen, and how upset I expect to feel."}, {"id": "f4", "type": "textarea", "label": "What actually happened, including how others reacted."}, {"id": "f5", "type": "textarea", "label": "What the extra effort was buying me, if anything."}, {"id": "f6", "type": "textarea", "label": "The standard I want to keep, and one I want to loosen."}]'::jsonb, array['perfectionism', 'behavioral experiment', 'core CBT']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('step-by-step-problem-solving-sheet', 'Step-by-Step Problem Solving Sheet', 'cbt'::resource_kind, 'A structured sheet that moves a client from naming a problem to brainstorming options, weighing them and trying one.', 'Use it to give a client a repeatable way to approach a problem that feels stuck.', array['Adults', 'Teens']::text[], '30 minutes', 'Start with a problem that is real and solvable, not a worry about something outside their control. Guide your client to state it in one concrete sentence, then brainstorm without judging. Judge options only after the list is long. Many clients skip the review step, so schedule a check-in on how the chosen plan went and what to adjust.', '[{"id": "f0", "type": "textarea", "label": "The problem, in one concrete sentence."}, {"id": "f1", "type": "textarea", "label": "What I would like to be different, specifically."}, {"id": "f2", "type": "textarea", "label": "All the options I can think of, even silly ones."}, {"id": "f3", "type": "textarea", "label": "Pros and cons of my top three options."}, {"id": "f4", "type": "textarea", "label": "The option I will try, and exactly when."}, {"id": "f5", "type": "textarea", "label": "What might get in the way, and my plan for that."}, {"id": "f6", "type": "textarea", "label": "How it went and what I will change next time."}]'::jsonb, array['problem solving', 'planning', 'core CBT']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('decision-compromise-circles', 'Decision Compromise Circles', 'couples'::resource_kind, 'Maps each partner''s non-negotiables and flexible areas on a decision so a couple can find overlap.', 'Help partners stuck on a decision find where they can bend and what each truly needs.', array['Couples']::text[], '20 to 30 minutes', 'Have each partner fill in the inner circle (what I cannot give up, and why it matters) and the outer circle (what I can flex on) before sharing. Read inner circles first, aloud, with the listener only reflecting back. Many couples find the inner circles are smaller and more compatible than they feared. Watch for a partner listing everything as essential, and ask what is underneath it.', '[{"id": "f0", "type": "textarea", "label": "Partner A inner circle: what I cannot give up on this decision"}, {"id": "f1", "type": "textarea", "label": "Partner A: the feeling or value behind it"}, {"id": "f2", "type": "textarea", "label": "Partner A outer circle: what I can flex on"}, {"id": "f3", "type": "textarea", "label": "Partner B inner circle: what I cannot give up on this decision"}, {"id": "f4", "type": "textarea", "label": "Partner B: the feeling or value behind it"}, {"id": "f5", "type": "textarea", "label": "Partner B outer circle: what I can flex on"}, {"id": "f6", "type": "textarea", "label": "One option that honors both inner circles"}]'::jsonb, array['decision making', 'compromise', 'Gottman']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('jealousy-reassurance-request-sheet', 'Jealousy Reassurance Request Sheet', 'couples'::resource_kind, 'Lets a partner name a jealous or insecure moment and ask for a specific kind of reassurance.', 'Turn jealous moments into clear requests instead of accusations or silent withdrawal.', array['Couples']::text[], '20 minutes', 'Partners often show jealousy as accusation or retreat, so this slows it down into a feeling, a story, and one concrete ask. The partner who feels jealous completes their side first; the other writes what they can offer and what they cannot promise. Keep the focus on reassurance and trust, not on proving anything, and check that the requests are realistic for both people.', '[{"id": "f0", "type": "textarea", "label": "What happened just before the jealous feeling showed up"}, {"id": "f1", "type": "textarea", "label": "The feeling in my body and the story I told myself"}, {"id": "f2", "type": "textarea", "label": "What I am afraid this means about us"}, {"id": "f3", "type": "textarea", "label": "One specific thing I would like to hear or see"}, {"id": "f4", "type": "textarea", "label": "Partner: what I can offer that is true for me"}, {"id": "f5", "type": "textarea", "label": "Partner: what I cannot promise, and what I can do instead"}, {"id": "f6", "type": "textarea", "label": "How we will check in about this again"}]'::jsonb, array['trust', 'jealousy', 'communication']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('phone-free-connection-agreement', 'Phone-Free Connection Agreement', 'couples'::resource_kind, 'Has a couple agree on when devices go away so shared time gets full attention.', 'Build a realistic, shared agreement about devices that protects time together.', array['Couples']::text[], '20 minutes', 'Device use is a common source of quiet resentment, and it goes better as a shared agreement than as one partner''s complaint. Have each partner describe how it feels when attention drifts, then choose one or two small windows to start, such as meals or the first ten minutes after reunion. Keep it specific and revisit it in a week. Notice whether either partner hears the request as blame.', '[{"id": "f0", "type": "textarea", "label": "How I feel when my partner is on a device during our time"}, {"id": "f1", "type": "textarea", "label": "What my own device use gives me, honestly"}, {"id": "f2", "type": "textarea", "label": "Times and places we will put devices away"}, {"id": "f3", "type": "textarea", "label": "What counts as an exception, such as work or family calls"}, {"id": "f4", "type": "textarea", "label": "What we will say when one of us slips"}, {"id": "f5", "type": "textarea", "label": "When we will review how this is going"}]'::jsonb, array['connection', 'technology', 'communication']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('daily-reunion-ritual-planner', 'Daily Reunion Ritual Planner', 'couples'::resource_kind, 'Designs a short, repeatable way for partners to greet each other after time apart.', 'Create a small daily reunion routine that sets the tone for the evening.', array['Couples']::text[], '20 minutes', 'The first few minutes after partners reunite often set the mood for the whole evening, yet most couples leave them to chance. Each partner names what they usually need on arrival, such as quiet, a hug, or a quick download, and the pair designs a short ritual that fits both. Start small, try it for a week, and adjust. Watch for one partner''s needs being quietly dropped.', '[{"id": "f0", "type": "textarea", "label": "What the first ten minutes at home usually look like for us"}, {"id": "f1", "type": "textarea", "label": "What I need when I arrive or when my partner arrives"}, {"id": "f2", "type": "textarea", "label": "What I would like my partner to do or not do"}, {"id": "f3", "type": "textarea", "label": "Our reunion ritual in one or two sentences"}, {"id": "f4", "type": "textarea", "label": "What gets in the way, and our backup plan"}, {"id": "f5", "type": "textarea", "label": "How it felt after a week of trying it"}]'::jsonb, array['rituals', 'connection', 'routines']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('five-year-shared-picture', 'Five-Year Shared Picture', 'couples'::resource_kind, 'Walks partners through describing a shared future one area at a time and noticing where they match.', 'Help partners talk about the future together and find shared direction.', array['Couples']::text[], 'Full session', 'Couples drifting along day to day sometimes have never described the future out loud. Each partner pictures a good ordinary day five years from now, covering home, work, family, friends, and rest, then they compare. Treat differences as information to explore, not a verdict. Note any area with strong feeling and revisit it with a dreams-within-conflict style conversation if needed.', '[{"id": "f0", "type": "textarea", "label": "Partner A: a good ordinary day five years from now"}, {"id": "f1", "type": "textarea", "label": "Partner B: a good ordinary day five years from now"}, {"id": "f2", "type": "textarea", "label": "Where our pictures match"}, {"id": "f3", "type": "textarea", "label": "Where our pictures differ or leave something out"}, {"id": "f4", "type": "textarea", "label": "One thing I am excited to build with you"}, {"id": "f5", "type": "textarea", "label": "One step we can take in the next three months"}]'::jsonb, array['goal setting', 'shared meaning', 'connection']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('pushing-away-container-practice', 'Pushing Away Container Practice', 'dbt'::resource_kind, 'Builds an imagined container where a client can set a painful topic aside on purpose, for now.', 'Give a client a way to set a topic down until a better time to face it.', array['Adults', 'Teens']::text[], '20 minutes', 'Frame this as a short break from a topic, never as denial. Have the client picture the container in detail, then practice placing one small worry in it during session before trying anything heavier. Agree on when the topic will be picked up again, so the client trusts the pause is temporary.', '[{"id": "f0", "type": "textarea", "label": "What is the topic I want to set down for now?"}, {"id": "f1", "type": "textarea", "label": "What does my container look like (material, size, lid, lock)?"}, {"id": "f2", "type": "textarea", "label": "Where does it sit, and what do I do to place the topic inside?"}, {"id": "f3", "type": "textarea", "label": "What will I do with my hands and attention right after I close it?"}, {"id": "f4", "type": "textarea", "label": "When and with whom will I come back to the topic?"}, {"id": "f5", "type": "textarea", "label": "What did I notice when I practiced with a small worry first?"}]'::jsonb, array['distress tolerance', 'pushing away', 'skills']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('mindfulness-of-current-emotions-log', 'Mindfulness of Current Emotions Log', 'dbt'::resource_kind, 'Guides a client to observe an emotion as it rises, peaks and fades, without pushing it or feeding it.', 'Practice noticing an emotion as a passing wave rather than a verdict on the day.', array['Adults', 'Teens']::text[], 'Ten minutes daily for two weeks', 'Pick a mild emotion for early practice. Clients often turn observing into judging, so listen for words like should and shouldn''t in the log and gently return them to description. Ask where the feeling lives in the body and how its intensity moved. Review one or two entries together each week.', '[{"id": "f0", "type": "textarea", "label": "What emotion did I notice, and what was happening just before?"}, {"id": "f1", "type": "textarea", "label": "Where did I feel it in my body?"}, {"id": "f2", "type": "textarea", "label": "How strong was it at the start, from 0 to 100?"}, {"id": "f3", "type": "textarea", "label": "What did I do to simply watch it, without fighting or feeding it?"}, {"id": "f4", "type": "textarea", "label": "How strong was it a few minutes later?"}, {"id": "f5", "type": "textarea", "label": "What judgments showed up, and how did I let them go?"}, {"id": "f6", "type": "textarea", "label": "What do I want to remember about this wave?"}]'::jsonb, array['emotion regulation', 'mindfulness', 'skills']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('one-mindfully-practice-log', 'One-Mindfully Practice Log', 'dbt'::resource_kind, 'Tracks everyday moments where a client does one thing at a time with full attention.', 'Strengthen attention by doing one activity at a time and returning when the mind wanders.', array['Adults', 'Teens', 'Groups']::text[], 'One week', 'Start with a low-stakes activity like washing a mug or walking to the car. Expect clients to report that their mind wandered and count it as failure; the return is the practice. Ask what helped them come back, and which routine task could become a daily anchor.', '[{"id": "f0", "type": "textarea", "label": "Which one activity did I choose to do one-mindfully today?"}, {"id": "f1", "type": "textarea", "label": "What was I tempted to do at the same time?"}, {"id": "f2", "type": "textarea", "label": "What did my mind wander to?"}, {"id": "f3", "type": "textarea", "label": "How did I bring my attention back?"}, {"id": "f4", "type": "textarea", "label": "What did I notice that I usually miss?"}, {"id": "f5", "type": "textarea", "label": "What activity will I try tomorrow?"}]'::jsonb, array['mindfulness', 'one-mindfully', 'attention']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('make-and-keep-friends-planner', 'Make and Keep Friends Planner', 'dbt'::resource_kind, 'Lays out steps for finding people, reaching out, and keeping a friendship warm over time.', 'Plan small, repeatable steps toward connection and maintaining the ones that matter.', array['Adults', 'Teens']::text[], '30 minutes', 'Useful when a client wants closeness but stalls at the first step. Keep the first action very small, such as one message or one invitation, and rehearse it aloud. Link the GIVE skills from earlier work to the keep-it-going section, and check back on what actually happened next session.', '[{"id": "f0", "type": "textarea", "label": "Who are two or three people I already know a little and could reach out to?"}, {"id": "f1", "type": "textarea", "label": "Where could I meet people who share an interest of mine?"}, {"id": "f2", "type": "textarea", "label": "What is one small first step I will take this week?"}, {"id": "f3", "type": "textarea", "label": "What will I say or write, word for word?"}, {"id": "f4", "type": "textarea", "label": "What worries come up, and how will I respond to them?"}, {"id": "f5", "type": "textarea", "label": "How will I show interest in the other person (GIVE)?"}, {"id": "f6", "type": "textarea", "label": "What will I do to keep this connection alive over the next month?"}]'::jsonb, array['interpersonal effectiveness', 'connection', 'GIVE']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('solve-or-accept-decision-sheet', 'Solve or Accept Decision Sheet', 'dbt'::resource_kind, 'Helps a client sort a painful situation into four options: solve it, change feelings, tolerate it, or stay stuck.', 'Choose deliberately between changing a problem and accepting it, rather than drifting.', array['Adults', 'Teens']::text[], '25 minutes', 'Walk through one real situation and let the client name all four options before choosing; staying miserable is included on purpose so the choice is visible. Notice whether the client defaults to fixing everything or accepting everything. Revisit the chosen option after a week and see what shifted.', '[{"id": "f0", "type": "textarea", "label": "What is the situation that is bothering me?"}, {"id": "f1", "type": "textarea", "label": "Could I solve it? What would that look like?"}, {"id": "f2", "type": "textarea", "label": "Could I change how I feel about it? How?"}, {"id": "f3", "type": "textarea", "label": "Could I accept and tolerate it as it is? What would help me do that?"}, {"id": "f4", "type": "textarea", "label": "What would staying miserable look like, and what does it cost me?"}, {"id": "f5", "type": "textarea", "label": "Which option am I choosing for now, and why?"}, {"id": "f6", "type": "textarea", "label": "What is my first step, and when will I take it?"}]'::jsonb, array['distress tolerance', 'radical acceptance', 'problem solving']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('body-clue-detective-game', 'Body Clue Detective Game', 'game'::resource_kind, 'Players draw situation cards and name the body clues that might show up, then trade guesses.', 'Build body awareness by linking everyday moments to physical sensations.', array['Teens', 'Adults', 'Groups']::text[], '20 minutes', 'Write ten to fifteen everyday situation cards together, some pleasant and some tense. Each player draws one and names the body clues that might show up, then others add guesses. Stress that there are no wrong sensations. Watch for a client who goes quiet on the tense cards, and let them pass without comment.', '[{"id": "f0", "type": "textarea", "label": "Situation cards we wrote"}, {"id": "f1", "type": "textarea", "label": "A body clue I named for myself"}, {"id": "f2", "type": "textarea", "label": "A clue someone else named that surprised me"}, {"id": "f3", "type": "textarea", "label": "A sensation that shows up in more than one situation"}, {"id": "f4", "type": "textarea", "label": "Which clue tells me first that something is shifting"}, {"id": "f5", "type": "textarea", "label": "One clue I will watch for this week"}]'::jsonb, array['body awareness', 'interoception', 'play']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('pause-button-pass-along-game', 'Pause Button Pass-Along Game', 'game'::resource_kind, 'A circle game where a prop passes only after the holder names a pause move before reacting.', 'Rehearse a short pause between a trigger and a reaction in a playful setting.', array['Children', 'Teens', 'Groups']::text[], '15 to 20 minutes', 'Pass a soft prop around while you read quick trigger cards such as a cut line or a surprise change of plan. The holder names one pause move before the prop moves on. Keep the pace brisk, then slow down for the debrief. Invite the group to notice which pause moves came easily and which felt silly, and let clients keep their own favorites.', '[{"id": "f0", "type": "textarea", "label": "Trigger cards we used"}, {"id": "f1", "type": "textarea", "label": "The pause move I picked most often"}, {"id": "f2", "type": "textarea", "label": "A pause move I heard from someone else that I want to try"}, {"id": "f3", "type": "textarea", "label": "What got in the way of pausing in the game"}, {"id": "f4", "type": "textarea", "label": "A real moment this week where a pause could help"}, {"id": "f5", "type": "textarea", "label": "What I will do first when that moment comes"}]'::jsonb, array['behavior', 'coping skills', 'group']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('perspective-swap-role-cards', 'Perspective Swap Role Cards', 'game'::resource_kind, 'Two players act out a short scene, then swap roles and replay it from the other seat.', 'Practice seeing a shared moment from another person''s point of view.', array['Teens', 'Adults', 'Groups']::text[], '25 minutes', 'Write short everyday scenes on cards, such as a late text or a borrowed item. Pairs act out the scene, swap seats, and replay it. Keep the scenes low-stakes at first and choose them together. Ask what each person felt and wanted in each seat. This builds understanding, not agreement, so avoid steering anyone toward deciding who was right.', '[{"id": "f0", "type": "textarea", "label": "The scene we played"}, {"id": "f1", "type": "textarea", "label": "What I felt and wanted in my first seat"}, {"id": "f2", "type": "textarea", "label": "What I felt and wanted after swapping"}, {"id": "f3", "type": "textarea", "label": "Something I noticed about the other seat"}, {"id": "f4", "type": "textarea", "label": "A situation in my life where I could try this swap"}, {"id": "f5", "type": "textarea", "label": "What I want to ask or say next time"}]'::jsonb, array['perspective', 'communication', 'relationships']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('plan-b-pitch-game', 'Plan B Pitch Game', 'game'::resource_kind, 'Teams pitch backup plans for a stuck problem card, then vote on which one they would try first.', 'Widen the list of options when one plan has stopped working.', array['Teens', 'Adults', 'Groups']::text[], '30 minutes', 'Give each team a stuck-problem card or let a client write their own. Teams get five minutes to pitch up to three backup plans, silly ones allowed, then everyone votes on one to try. The playful rules take pressure off and help rigid thinking loosen. Ask the client to pick one small step from the winning pitch, and leave the final choice to them.', '[{"id": "f0", "type": "textarea", "label": "The stuck problem on my card"}, {"id": "f1", "type": "textarea", "label": "Plans pitched by my team"}, {"id": "f2", "type": "textarea", "label": "The silliest plan, and anything useful hiding in it"}, {"id": "f3", "type": "textarea", "label": "The plan I would try first"}, {"id": "f4", "type": "textarea", "label": "The smallest first step for that plan"}, {"id": "f5", "type": "textarea", "label": "Who or what could support me with it"}]'::jsonb, array['problem solving', 'flexibility', 'decisions']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('energy-battery-cards-game', 'Energy Battery Cards Game', 'game'::resource_kind, 'Players sort activity cards into drains and chargers, then build a balanced day with limited battery.', 'Notice what spends and restores energy, and plan a day that fits it.', array['Adults', 'Teens', 'Groups']::text[], '25 minutes', 'Make activity cards together, everyday items such as a phone call, a walk, or cleaning. Players sort them into drains, chargers, or both, then plan a day within ten battery points. Expect disagreement, because the same card can be a drain for one person and a charger for another. Use that to talk about pacing, and let the client set the point values.', '[{"id": "f0", "type": "textarea", "label": "Cards I sorted as drains"}, {"id": "f1", "type": "textarea", "label": "Cards I sorted as chargers"}, {"id": "f2", "type": "textarea", "label": "A card that was both, and why"}, {"id": "f3", "type": "textarea", "label": "My day plan within ten points"}, {"id": "f4", "type": "textarea", "label": "What I would trade out if the day ran long"}, {"id": "f5", "type": "textarea", "label": "One charger I will add this week"}]'::jsonb, array['energy', 'pacing', 'planning']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('mood-soundtrack-drawing', 'Mood Soundtrack Drawing', 'kids'::resource_kind, 'The child draws what each feeling would sound like, using wavy, spiky or soft lines and colors.', 'Give a child a playful, wordless way to describe feelings they cannot yet name.', array['Children']::text[], '20 minutes', 'Offer paper, crayons and markers, and let the child draw sound waves instead of faces. Some children can show a feeling long before they can say it. Ask about the loudest and quietest drawings, and invite the parent to guess first, then hear the child''s answer.', '[{"id": "f0", "type": "textarea", "label": "Draw what a happy feeling sounds like. How loud is it?"}, {"id": "f1", "type": "textarea", "label": "Draw what a mad feeling sounds like."}, {"id": "f2", "type": "textarea", "label": "Draw what a worried feeling sounds like."}, {"id": "f3", "type": "textarea", "label": "Draw what a calm feeling sounds like."}, {"id": "f4", "type": "textarea", "label": "Which sound drawing is the loudest, and why?"}, {"id": "f5", "type": "textarea", "label": "What sound would I like to hear more of this week?"}]'::jsonb, array['emotion identification', 'children', 'art']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('five-finger-helpers-hand', 'Five Finger Helpers Hand', 'kids'::resource_kind, 'The child traces a hand and names a helper, grown-up or friend, on each finger to build a circle of support.', 'Help a child see the people they can turn to when a feeling gets big.', array['Children']::text[], '20 minutes', 'Trace the child''s hand and let them decorate it. Each finger holds one person or helper, and the palm holds the child''s own best calming move. Younger children may need help finding more than two names, so include pets, teachers and neighbors. Send the hand home for the parent to post on the fridge.', '[{"id": "f0", "type": "textarea", "label": "Thumb: someone at home I can go to"}, {"id": "f1", "type": "textarea", "label": "Pointer finger: someone at school who helps me"}, {"id": "f2", "type": "textarea", "label": "Middle finger: a friend who is kind to me"}, {"id": "f3", "type": "textarea", "label": "Ring finger: another grown-up I trust"}, {"id": "f4", "type": "textarea", "label": "Pinky: a helper that is not a person, like a pet or a toy"}, {"id": "f5", "type": "textarea", "label": "Palm: the thing I can do by myself to feel calmer"}]'::jsonb, array['support', 'children', 'art']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('feelings-matching-card-game', 'Feelings Matching Card Game', 'kids'::resource_kind, 'The child and clinician make a deck of paired feeling cards, then play a memory match and share a story for each pair.', 'Practice naming feelings and the moments that bring them through a turn-taking game.', array['Children']::text[], '30 minutes', 'Make about eight pairs of index cards together, one card with a drawn face and one with a color or symbol for the same feeling. Play memory match, and each time a pair is found the player tells a moment they felt that way. Parents can join as a player and share their own stories, which shows that grown-ups have feelings too.', '[{"id": "f0", "type": "textarea", "label": "Which feelings did we put in our deck?"}, {"id": "f1", "type": "textarea", "label": "Which pair was easiest to draw?"}, {"id": "f2", "type": "textarea", "label": "Which pair was hardest to draw?"}, {"id": "f3", "type": "textarea", "label": "Tell about a time I felt this feeling."}, {"id": "f4", "type": "textarea", "label": "Which feeling would I like to play again at home?"}, {"id": "f5", "type": "textarea", "label": "Who will I play this game with at home?"}]'::jsonb, array['emotion identification', 'children', 'play']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('stoplight-solutions-poster', 'Stoplight Solutions Poster', 'kids'::resource_kind, 'The child builds a red, yellow and green poster for stopping, thinking of choices and trying one.', 'Teach a child a simple pause-and-choose routine for everyday problems.', array['Children']::text[], '25 minutes', 'Have the child color three circles on a poster, red to stop and breathe, yellow to think of two or three ideas, green to try one. Practice with a small pretend problem such as a toy someone else is using. The parent learns the colors too and can say the color word as a gentle cue at home rather than giving the answer.', '[{"id": "f0", "type": "textarea", "label": "Red light: what I do to stop my body"}, {"id": "f1", "type": "textarea", "label": "Yellow light: my first idea for solving a problem"}, {"id": "f2", "type": "textarea", "label": "Yellow light: my second idea"}, {"id": "f3", "type": "textarea", "label": "Green light: the idea I want to try"}, {"id": "f4", "type": "textarea", "label": "What happened when I tried it?"}, {"id": "f5", "type": "textarea", "label": "What color word can my grown-up say to remind me?"}]'::jsonb, array['problem solving', 'children', 'regulation', 'routines']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('cozy-corner-blueprint', 'Cozy Corner Blueprint', 'kids'::resource_kind, 'The child draws and then builds a small calm space at home from pillows, blankets and favorite things.', 'Give a child a chosen, predictable place to settle when feelings get big.', array['Children']::text[], '30 minutes', 'Start by letting the child draw a blueprint, then plan the real corner with the parent. The child chooses what goes in it, and the parent agrees it is never used as a punishment or a place to be sent. Review what worked and what to change after the first week.', '[{"id": "f0", "type": "textarea", "label": "Draw my cozy corner and label what is in it."}, {"id": "f1", "type": "textarea", "label": "Where in our home will it go?"}, {"id": "f2", "type": "textarea", "label": "Three things I want in my corner"}, {"id": "f3", "type": "textarea", "label": "What helps my body feel calm there?"}, {"id": "f4", "type": "textarea", "label": "How will I know when I want to go there?"}, {"id": "f5", "type": "textarea", "label": "What will my grown-up do when I am in my corner?"}]'::jsonb, array['self-soothing', 'children', 'sensory', 'parenting']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('work-to-home-transition-ritual-planner', 'Work-to-Home Transition Ritual Planner', 'worksheet'::resource_kind, 'Helps a client design a short ritual that marks the shift from work mode to home mode.', 'Build a small, repeatable transition so the workday stops spilling into the evening.', array['Adults']::text[], '20 minutes', 'Some clients carry the day''s tension through the door and find the evening is gone before they notice. Use this to name what they are still carrying at the end of work, pick one small cue that marks a stopping point, and plan how it fits the actual commute or routine. Keep it small enough to repeat on a tired day, and review in session how it went.', '[{"id": "f0", "type": "textarea", "label": "What I usually carry home from work in my mind or body"}, {"id": "f1", "type": "textarea", "label": "What the first hour at home looks like right now"}, {"id": "f2", "type": "textarea", "label": "One small action that could mark the end of my workday"}, {"id": "f3", "type": "textarea", "label": "Where and when I would do it, even on a busy day"}, {"id": "f4", "type": "textarea", "label": "What I want to be able to give the evening"}, {"id": "f5", "type": "textarea", "label": "How I will notice if the ritual helps, and what I will adjust"}]'::jsonb, array['routines', 'stress', 'work']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('savoring-moments-log', 'Savoring Moments Log', 'worksheet'::resource_kind, 'Has a client capture small pleasant moments and notice what made each one register.', 'Train attention toward ordinary good moments so they are noticed and remembered.', array['Adults', 'Teens']::text[], '10 minutes a day for a week', 'Clients with a heavy week often say nothing good happened, because the small moments went by unnoticed. Ask for one brief entry a day: what the moment was, what the senses picked up, and how long the client stayed with it. In session, look for patterns in what supports these moments and plan to make room for more of them. Go at the client''s pace and never push positivity.', '[{"id": "f0", "type": "textarea", "label": "The moment I noticed today"}, {"id": "f1", "type": "textarea", "label": "What I could see, hear, smell, taste or feel in it"}, {"id": "f2", "type": "textarea", "label": "How long I stayed with it before moving on"}, {"id": "f3", "type": "textarea", "label": "What made it possible, such as a person, a place or a pace"}, {"id": "f4", "type": "textarea", "label": "One thing I could do to give myself another moment like it"}]'::jsonb, array['savoring', 'behavioral activation', 'monitoring']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('automatic-yes-audit', 'Automatic Yes Audit', 'worksheet'::resource_kind, 'Looks at recent times a client said yes without thinking, and what it cost them.', 'Slow down automatic agreement so the client can choose what to take on.', array['Adults', 'Teens']::text[], '25 minutes', 'Clients who agree on reflex often feel stretched thin and resentful without seeing the pattern. Work through three recent yeses: what was asked, what the client felt in the moment, and what saying yes cost them afterward. Then draft a pause phrase they can use to buy time. Explore in session what makes a no feel risky, and keep the choice about whether to decline with the client.', '[{"id": "f0", "type": "textarea", "label": "A recent time I said yes right away"}, {"id": "f1", "type": "textarea", "label": "What I felt in my body when I was asked"}, {"id": "f2", "type": "textarea", "label": "What I was afraid would happen if I said no"}, {"id": "f3", "type": "textarea", "label": "What saying yes cost me afterward"}, {"id": "f4", "type": "textarea", "label": "A pause phrase I could use to buy myself time"}, {"id": "f5", "type": "textarea", "label": "One request I could revisit or renegotiate this week"}]'::jsonb, array['boundaries', 'assertiveness', 'people-pleasing']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('difficult-conversation-prep-sheet', 'Difficult Conversation Prep Sheet', 'worksheet'::resource_kind, 'Guides a client through preparing for one hard conversation, from goal to opening line.', 'Prepare for a hard talk so the client says what matters instead of freezing or exploding.', array['Adults', 'Teens']::text[], '30 minutes', 'Use this when a client is putting off a conversation or fears it will go badly. They clarify what they actually want from it, the main point in one sentence, an opening line, and a plan for what to do if the other person reacts strongly. Rehearse the opening aloud in session. The client decides whether and when the conversation happens, and the sheet works just as well for deciding not to have it.', '[{"id": "f0", "type": "textarea", "label": "Who the conversation is with and what it is about"}, {"id": "f1", "type": "textarea", "label": "What I hope will be different afterward"}, {"id": "f2", "type": "textarea", "label": "The one sentence I most want them to hear"}, {"id": "f3", "type": "textarea", "label": "How I could open the conversation"}, {"id": "f4", "type": "textarea", "label": "What the other person might say, and how I might respond"}, {"id": "f5", "type": "textarea", "label": "What I can do to steady myself beforehand and afterward"}, {"id": "f6", "type": "textarea", "label": "When and where I would choose to have it, or whether I will"}]'::jsonb, array['communication', 'assertiveness', 'rehearsal']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('weekly-reset-review', 'Weekly Reset Review', 'worksheet'::resource_kind, 'Gives a client a brief end-of-week look back and a plan for the week ahead.', 'Close one week and set up the next with a short, steady habit of review.', array['Adults', 'Teens']::text[], '20 minutes', 'A short weekly look back helps clients see what is working before the next week fills up. Have the client note what went well, what drained them, and one thing they learned, then choose one or two realistic priorities. Bring the sheet to session as a ready-made agenda. Keep entries brief and non-judging; a week with little to report is still useful information.', '[{"id": "f0", "type": "textarea", "label": "One thing from this week that I am glad about"}, {"id": "f1", "type": "textarea", "label": "One thing that drained me more than I expected"}, {"id": "f2", "type": "textarea", "label": "Something this week taught me about what I need"}, {"id": "f3", "type": "textarea", "label": "What I want to carry into next week"}, {"id": "f4", "type": "textarea", "label": "One or two realistic priorities for next week"}, {"id": "f5", "type": "textarea", "label": "One thing I can let go of or lower the bar on"}, {"id": "f6", "type": "textarea", "label": "Who or what could support me with next week"}]'::jsonb, array['review', 'goal setting', 'routines']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('five-senses-orienting-round', 'Five Senses Orienting Round', 'worksheet'::resource_kind, 'A client names what they notice in the room through each sense to anchor attention in the present.', 'Help a client orient to the here and now using what the room offers right now.', array['Adults', 'Teens']::text[], '10 minutes', 'Use this at the start or end of a session, or when your client seems pulled away from the room. Go at your client''s pace and let them skip any sense. It stays in the present on purpose: nothing here asks about what happened, and you decide when it fits. Invite them to keep a copy for use between sessions.', '[{"id": "f0", "type": "textarea", "label": "Something I can see that is calm or neutral"}, {"id": "f1", "type": "textarea", "label": "Something I can hear right now"}, {"id": "f2", "type": "textarea", "label": "Something I can feel touching my body, like the chair or my feet"}, {"id": "f3", "type": "textarea", "label": "A smell or taste I notice, or one I would choose"}, {"id": "f4", "type": "textarea", "label": "Where I am, what day it is, and one thing that tells me I am safe now"}]'::jsonb, array['PTSD and trauma', 'grounding', 'orienting']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('wave-riding-skills-card', 'Wave Riding Skills Card', 'dbt'::resource_kind, 'A pocket card that lists distress tolerance steps a client picks from when a reminder of the past surges.', 'Build a short, personal list of skills a client can reach for when a surge of distress arrives.', array['Adults', 'Teens']::text[], '15 minutes', 'Work through the card together so it fits your client''s body and daily life, using distress tolerance skills such as paced breathing, temperature change, and self-soothing with the senses. Rehearse one in session when your client is calm. If thoughts of self-harm come up, complete 988 (call or text) with them in session and keep your own safety steps in place.', '[{"id": "f0", "type": "textarea", "label": "A sign in my body that a surge is starting"}, {"id": "f1", "type": "textarea", "label": "A skill using temperature or movement that helps me"}, {"id": "f2", "type": "textarea", "label": "A skill using my senses that settles me"}, {"id": "f3", "type": "textarea", "label": "A slow breathing pattern I can do for one minute"}, {"id": "f4", "type": "textarea", "label": "A kind sentence I can say to myself while it passes"}, {"id": "f5", "type": "textarea", "label": "A person I can text, and 988 (call or text) if I feel unsafe"}]'::jsonb, array['PTSD and trauma', 'distress tolerance', 'skills']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('safe-helper-circle-drawing', 'Safe Helper Circle Drawing', 'kids'::resource_kind, 'A child draws a circle of safe people and places, while a parent helps name who is on the team.', 'Help a child see the trusted people and safe places around them.', array['Children']::text[], '20 minutes', 'The child draws themselves in the middle of a page with safe people and places around them, and the parent sits alongside, adds names the child asks for, and listens without questioning. The drawing is only about safety and support, so do not ask for details of any scary event. Remind the parent that you and they have reporting duties if a child discloses harm, and tell them how you will handle it.', '[{"id": "f0", "type": "textarea", "label": "The people I draw in my circle"}, {"id": "f1", "type": "textarea", "label": "The places where I feel safe"}, {"id": "f2", "type": "textarea", "label": "Who I can tell when I feel scared"}, {"id": "f3", "type": "textarea", "label": "One thing that helps my body feel calm"}, {"id": "f4", "type": "textarea", "label": "What my grown-up can do when I feel scared"}]'::jsonb, array['PTSD and trauma', 'children', 'safety']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('trigger-plan-for-two', 'Trigger Plan for Two', 'couples'::resource_kind, 'Partners each name what helps and what does not when a reminder hits, then agree on a shared plan.', 'Help partners agree on how to support each other when one is hit by a reminder.', array['Couples']::text[], '30 minutes', 'Partner A, who lives with the reminders, names signals, helpful responses, and unhelpful ones in their own words and chooses how much to share. Partner B names what they feel and need while supporting, and what they can offer. Keep it to the present plan and pacing; no one needs to describe the past. Stop and slow down if either partner floods.', '[{"id": "f0", "type": "textarea", "label": "Partner A: early signs that a reminder has hit"}, {"id": "f1", "type": "textarea", "label": "Partner A: what helps when that happens"}, {"id": "f2", "type": "textarea", "label": "Partner A: what does not help right now"}, {"id": "f3", "type": "textarea", "label": "Partner B: what I feel when I see this happen"}, {"id": "f4", "type": "textarea", "label": "Partner B: what I can offer and what I need for myself"}, {"id": "f5", "type": "textarea", "label": "What we both agree to do, and a word for taking a pause"}]'::jsonb, array['PTSD and trauma', 'partners', 'support']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('safe-landing-spots-game', 'Safe Landing Spots Game', 'game'::resource_kind, 'Players take turns naming places, objects, or people that bring a feeling of safety, building a shared board.', 'Help a group or family build a bank of safe landing spots through simple turn-taking play.', array['Groups', 'Teens', 'Children']::text[], '20 minutes', 'Each player draws a card with a prompt, such as a place that feels calm or a smell that is comforting, and answers or passes. Players earn a token for each answer and for each kind comment, and anyone may pass without comment. Debrief by asking which spots they could use this week. Keep every prompt in the present and stop any share that heads toward details of past events.', '[{"id": "f0", "type": "textarea", "label": "The safe place or thing I named"}, {"id": "f1", "type": "textarea", "label": "What I notice in my body when I picture it"}, {"id": "f2", "type": "textarea", "label": "A spot someone else named that I would like to try"}, {"id": "f3", "type": "textarea", "label": "One landing spot I will use this week"}, {"id": "f4", "type": "textarea", "label": "What helped me take part today"}]'::jsonb, array['PTSD and trauma', 'grounding', 'safety']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('worry-postponement-planner', 'Worry Postponement Planner', 'cbt'::resource_kind, 'A client schedules a daily worry window and jots worries down to return to later.', 'Help a client practice postponing worries and choose which ones need a step.', array['Adults', 'Teens']::text[], '15 minutes', 'Agree on a fixed 15 minute window and a spot to park worries during the day. At the window, your client sorts each worry into one that has a step they can take and one they cannot act on. Check how it went at the next session and adjust the time or length to what is realistic for them. Use your judgment about fit.', '[{"id": "f0", "type": "textarea", "label": "My worry window time and place"}, {"id": "f1", "type": "textarea", "label": "A worry that came up and when"}, {"id": "f2", "type": "textarea", "label": "What I told myself to wait until the window"}, {"id": "f3", "type": "textarea", "label": "Worries with a step I can take"}, {"id": "f4", "type": "textarea", "label": "Worries I cannot act on right now"}, {"id": "f5", "type": "textarea", "label": "What I noticed after the window ended"}]'::jsonb, array['anxiety', 'worry', 'thought records']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('anxiety-passengers-on-the-bus', 'Anxiety Passengers on the Bus', 'act'::resource_kind, 'A client pictures anxious thoughts as passengers on a bus while they keep driving toward a valued direction.', 'Help a client act toward a value while anxious thoughts and feelings come along.', array['Adults', 'Teens']::text[], '20 minutes', 'Invite your client to imagine driving a bus toward something that matters to them, with anxious thoughts and sensations as noisy passengers. The task is not to throw them off the bus but to keep driving. Link the metaphor to one small action this week, and let your client adapt the image to something that suits them better.', '[{"id": "f0", "type": "textarea", "label": "Where my bus is headed and why it matters"}, {"id": "f1", "type": "textarea", "label": "Passengers on my bus, the loudest anxious thoughts"}, {"id": "f2", "type": "textarea", "label": "What each passenger tells me to do"}, {"id": "f3", "type": "textarea", "label": "What happens when I let them shout and keep driving"}, {"id": "f4", "type": "textarea", "label": "One small action toward my direction this week"}]'::jsonb, array['anxiety', 'values', 'defusion']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('worry-weather-report-craft', 'Worry Weather Report Craft', 'kids'::resource_kind, 'A child makes a weather report for their worries, with a parent as the helpful forecaster.', 'Help a child name the size of a worry and what could help it pass like weather.', array['Children']::text[], '25 minutes', 'The child draws a weather map for the day, with sunny, cloudy, or stormy spots standing for how big their worries feel, and presents it like a forecaster. The parent listens, asks which weather it is, and shares one calm thing to try. Remind the parent that clouds pass and that the child does not need to be talked out of the feeling. Check in on how the parent responded.', '[{"id": "f0", "type": "textarea", "label": "Today''s weather in my body, drawn as sun, clouds, or storm"}, {"id": "f1", "type": "textarea", "label": "The worry that is the biggest cloud"}, {"id": "f2", "type": "textarea", "label": "Something that helps a storm pass"}, {"id": "f3", "type": "textarea", "label": "What my grown-up said or did that helped"}, {"id": "f4", "type": "textarea", "label": "My forecast for tomorrow"}]'::jsonb, array['anxiety', 'children', 'worry']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('worry-detective-card-game', 'Worry Detective Card Game', 'game'::resource_kind, 'Players draw worry cards and take turns sorting each as a clue, a guess, or a fact.', 'Help players practice telling facts from guesses when worry sounds sure.', array['Groups', 'Teens', 'Children']::text[], '20 minutes', 'Write worry statements on cards, or have each player add their own. On each turn the player draws a card, reads it aloud, and decides whether it is a fact, a guess, or a clue worth checking, and the others may add a vote. Players earn a point for each worry they can turn into something to check. Debrief on which worries sounded the surest and what was most surprising.', '[{"id": "f0", "type": "textarea", "label": "A worry card I drew"}, {"id": "f1", "type": "textarea", "label": "Whether I called it a fact, a guess, or a clue and why"}, {"id": "f2", "type": "textarea", "label": "What I could check to find out"}, {"id": "f3", "type": "textarea", "label": "A worry I would like to test this week"}, {"id": "f4", "type": "textarea", "label": "What I noticed about my own worry voice"}]'::jsonb, array['anxiety', 'worry', 'thinking skills']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('calm-body-check-in-sheet', 'Calm Body Check-In Sheet', 'worksheet'::resource_kind, 'A client tracks where anxiety shows up in the body and which small steps ease it.', 'Help a client notice early body signals and match them with a helpful next step.', array['Adults', 'Teens']::text[], '15 minutes', 'Use this over a week so your client can see patterns in when and where their body signals show up. They log the situation, the sensation, and one small step they tried, without needing to judge it. Review the page together and pick one step to keep. It is a record for conversation, and you decide what it means.', '[{"id": "f0", "type": "textarea", "label": "The situation I was in"}, {"id": "f1", "type": "textarea", "label": "Where I felt it in my body"}, {"id": "f2", "type": "textarea", "label": "How strong it felt from 1 to 10"}, {"id": "f3", "type": "textarea", "label": "A small step I tried"}, {"id": "f4", "type": "textarea", "label": "What happened to the feeling afterward"}, {"id": "f5", "type": "textarea", "label": "What I would try next time"}]'::jsonb, array['anxiety', 'body signals', 'self-monitoring']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('thought-balance-sheet-for-low-mood', 'Thought Balance Sheet for Low Mood', 'cbt'::resource_kind, 'A client writes a heavy thought, then lists what supports it, what does not, and a more balanced version.', 'Help a client look at low mood thoughts from more than one side.', array['Adults', 'Teens']::text[], '20 minutes', 'Choose one heavy thought from this week, and let your client write it as they heard it. They look at what supports it and what leaves something out, then write a balanced version they could say to a friend. Go slowly, because the balanced version should feel believable. If thoughts of self-harm come up, complete 988 (call or text) with them in session.', '[{"id": "f0", "type": "textarea", "label": "The heavy thought as I heard it"}, {"id": "f1", "type": "textarea", "label": "What makes this thought feel true"}, {"id": "f2", "type": "textarea", "label": "What this thought leaves out"}, {"id": "f3", "type": "textarea", "label": "What I would say to a friend with this thought"}, {"id": "f4", "type": "textarea", "label": "A more balanced version I find believable"}, {"id": "f5", "type": "textarea", "label": "If I ever feel unsafe, I will call or text 988 and tell"}]'::jsonb, array['depression', 'thought records', 'low mood']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('values-compass-for-heavy-days', 'Values Compass for Heavy Days', 'act'::resource_kind, 'A client names what matters, then picks one tiny action that fits that value on a low-energy day.', 'Help a client choose small, value-led actions even when motivation is low.', array['Adults', 'Teens']::text[], '20 minutes', 'Ask your client to name two or three values, then scale each to something doable on their lowest-energy day, such as a text, a short walk, or watering a plant. The point is action before mood changes, not waiting to feel ready. Review which actions felt meaningful, not just which were finished.', '[{"id": "f0", "type": "textarea", "label": "A value that matters to me"}, {"id": "f1", "type": "textarea", "label": "What it looks like on a good day"}, {"id": "f2", "type": "textarea", "label": "What a tiny version looks like on a heavy day"}, {"id": "f3", "type": "textarea", "label": "What my mind says when I try it"}, {"id": "f4", "type": "textarea", "label": "What I did and how it felt"}, {"id": "f5", "type": "textarea", "label": "The next small action I will choose"}]'::jsonb, array['depression', 'values', 'committed action']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('reaching-out-without-pressure-sheet', 'Reaching Out Without Pressure Sheet', 'couples'::resource_kind, 'Both partners name how low mood shows up and what small, low-pressure connection can look like.', 'Help partners find small ways to stay connected during low mood without added pressure.', array['Couples']::text[], '30 minutes', 'Partner A describes what low mood feels like and what small contact helps, while Partner B names what they notice and what they need to keep going themselves. Together they choose two low-pressure ways to connect this week, such as sitting together or a short walk. Keep it about the two of them, and slow down if either partner feels blamed.', '[{"id": "f0", "type": "textarea", "label": "Partner A: how low mood shows up for me"}, {"id": "f1", "type": "textarea", "label": "Partner A: a small kind of contact that helps"}, {"id": "f2", "type": "textarea", "label": "Partner B: what I notice and how I feel about it"}, {"id": "f3", "type": "textarea", "label": "Partner B: what I need so I can keep supporting"}, {"id": "f4", "type": "textarea", "label": "Two low-pressure ways we will connect this week"}, {"id": "f5", "type": "textarea", "label": "A signal we use when one of us needs space"}]'::jsonb, array['depression', 'partners', 'connection']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('self-care-pairs-skill-sheet', 'Self-Care Pairs Skill Sheet', 'dbt'::resource_kind, 'A client pairs a skill for the body with a skill for the mind to plan around low mood days.', 'Help a client build a go-to plan using body-based and mind-based skills.', array['Adults', 'Teens']::text[], '20 minutes', 'Use the idea of taking care of the body first, such as sleep, movement, and eating regularly, and then add a skill for the mind. Your client builds pairs they can pick up when mood is low, and tries one between sessions. Adapt each pair to what is realistic for them. If hopeless thoughts come up, complete 988 (call or text) with them in session.', '[{"id": "f0", "type": "textarea", "label": "A body-based step that helps me, like rest or movement"}, {"id": "f1", "type": "textarea", "label": "A mind-based skill that helps me"}, {"id": "f2", "type": "textarea", "label": "One pair I will try this week"}, {"id": "f3", "type": "textarea", "label": "What gets in the way of the pair"}, {"id": "f4", "type": "textarea", "label": "What I will do about that"}, {"id": "f5", "type": "textarea", "label": "If I feel unsafe, I will call or text 988"}]'::jsonb, array['depression', 'emotion regulation', 'self-care']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('weekly-energy-budget-sheet', 'Weekly Energy Budget Sheet', 'worksheet'::resource_kind, 'A client lists tasks and rates how much energy each takes, then plans a week that fits.', 'Help a client plan a week around real energy levels, without guilt.', array['Adults', 'Teens']::text[], '20 minutes', 'Work with your client to list weekly tasks and rate each one low, medium, or high effort, then place them across days so heavy ones are spread out and rests are included. The page is a planning aid that you review together at the next session. Ask what felt doable and what needs adjusting rather than what was missed.', '[{"id": "f0", "type": "textarea", "label": "Tasks I have this week"}, {"id": "f1", "type": "textarea", "label": "Low effort tasks"}, {"id": "f2", "type": "textarea", "label": "Medium effort tasks"}, {"id": "f3", "type": "textarea", "label": "High effort tasks"}, {"id": "f4", "type": "textarea", "label": "How I will spread them across the days"}, {"id": "f5", "type": "textarea", "label": "What rest looks like for me this week"}]'::jsonb, array['depression', 'energy', 'planning']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('interruption-recovery-card', 'Interruption Recovery Card', 'worksheet'::resource_kind, 'A card where a client plans how to find their way back to a task after a phone buzz, a question or a wandering thought.', 'Help a client build a short, repeatable way back to the task after being pulled away.', array['Adults', 'Teens']::text[], '20 minutes, then a week of use', 'Have the client name the interruptions that happen most, then write one sentence to leave behind before stepping away so the task is easy to restart. Notice whether the client blames themselves for drifting; the card is about the return, not about never drifting. Review it a week later and keep only the steps they actually used.', '[{"id": "f0", "type": "textarea", "label": "The interruptions that pull me away most often"}, {"id": "f1", "type": "textarea", "label": "What I will write down before I step away from a task"}, {"id": "f2", "type": "textarea", "label": "The first small step I will take when I come back"}, {"id": "f3", "type": "textarea", "label": "A cue I can put where I will see it"}, {"id": "f4", "type": "textarea", "label": "What I did when I got pulled away this week"}, {"id": "f5", "type": "textarea", "label": "What I will change on the card"}]'::jsonb, array['ADHD', 'attention', 'routines']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('hyperfocus-exit-plan', 'Hyperfocus Exit Plan', 'cbt'::resource_kind, 'A thought-and-behavior plan for noticing deep absorption and stepping out of it on purpose when something else matters.', 'Give a client a way to leave absorbing activity at a chosen time without feeling jolted or resentful.', array['Adults', 'Teens']::text[], '30 minutes', 'Use this with a client who loses hours to an engaging task and then misses meals, appointments or people. Work out the thoughts that keep them in (just five more minutes) and the cost afterward, then design an exit cue and a landing activity. Choose the cue together; one that feels punishing will not last.', '[{"id": "f0", "type": "textarea", "label": "An activity that absorbs me completely"}, {"id": "f1", "type": "textarea", "label": "What it costs me when I stay too long"}, {"id": "f2", "type": "textarea", "label": "Thoughts that keep me going (just five more minutes)"}, {"id": "f3", "type": "textarea", "label": "A cue that will reach me, such as an alarm or a person"}, {"id": "f4", "type": "textarea", "label": "A small landing activity for after I stop"}, {"id": "f5", "type": "textarea", "label": "How the exit went this week"}]'::jsonb, array['ADHD', 'self-monitoring', 'behavioral']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('values-and-distraction-choice-point', 'Values and Distraction Choice Point', 'act'::resource_kind, 'An ACT choice point drawn for moments of distraction, naming what pulls away and what the client wants to move toward.', 'Help a client notice a distracted moment as a choice and steer toward what matters to them.', array['Adults', 'Teens']::text[], '25 minutes', 'Draw the choice point with the client: the situation at the center, hooks and urges to drift on one side, valued actions on the other. Keep the tone curious and avoid framing drifting as failure. Pick one ordinary moment, such as starting homework or a work email, and rehearse a single move toward what matters.', '[{"id": "f0", "type": "textarea", "label": "A moment this week when my attention got pulled away"}, {"id": "f1", "type": "textarea", "label": "The thoughts, feelings and urges that showed up"}, {"id": "f2", "type": "textarea", "label": "What pulled me away from what I care about"}, {"id": "f3", "type": "textarea", "label": "What I care about in that situation"}, {"id": "f4", "type": "textarea", "label": "One small move toward that I can try next time"}, {"id": "f5", "type": "textarea", "label": "How I will notice the choice point"}]'::jsonb, array['ADHD', 'core ACT', 'choice point', 'values']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('shared-calendar-check-in-routine', 'Shared Calendar Check-In Routine', 'couples'::resource_kind, 'A weekly sit-down where both partners look at the shared calendar and name their own parts in keeping it running.', 'Help partners share planning without one becoming the reminder keeper.', array['Couples']::text[], '30 minutes weekly', 'Both partners name their own part: the partner with attention difficulties picks which reminders they want and how, and the other partner agrees to say the reminder once, kindly, rather than repeat it. Watch for the parent-child dynamic and name it gently. Each partner writes their own answers, then they compare.', '[{"id": "f0", "type": "textarea", "label": "Partner A: the reminders I want and how I want them"}, {"id": "f1", "type": "textarea", "label": "Partner B: how I will remind once, kindly"}, {"id": "f2", "type": "textarea", "label": "Partner A: a task I will own this week"}, {"id": "f3", "type": "textarea", "label": "Partner B: a task I will own this week"}, {"id": "f4", "type": "textarea", "label": "What helped us stay on the same page"}, {"id": "f5", "type": "textarea", "label": "What we will change next week"}]'::jsonb, array['ADHD', 'couples', 'scheduling']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('morning-mission-map', 'Morning Mission Map', 'kids'::resource_kind, 'A child draws a map of morning stops, such as clothes, breakfast and backpack, and the parent walks it with them.', 'Help a child learn a morning sequence through a picture instead of repeated reminders.', array['Children']::text[], '30 minutes to draw, then one week of use', 'The child draws a map of the morning with a picture at each stop; the parent walks it with them for a few days, pointing to the next stop rather than giving orders, and praises each stop reached. If a child discloses something worrying while drawing, remember your reporting duties. Let the child add stops and decorate it.', '[{"id": "f0", "type": "textarea", "label": "The stops on my morning map"}, {"id": "f1", "type": "textarea", "label": "The stop that is hardest for me"}, {"id": "f2", "type": "textarea", "label": "What my parent can do to help at that stop"}, {"id": "f3", "type": "textarea", "label": "A fun thing at the end of the map"}, {"id": "f4", "type": "textarea", "label": "Which stops I reached this week"}]'::jsonb, array['ADHD', 'children', 'routines', 'parenting']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('support-call-script-card', 'Support Call Script Card', 'worksheet'::resource_kind, 'A short script card a client can read aloud when an urge is strong and they want to reach a supportive person.', 'Make reaching out during an urge easier by planning the words ahead of time.', array['Adults']::text[], '20 minutes', 'Have the client choose one or two people and write the exact words they would say, including a plain request such as stay on the phone with me. People often skip this step because asking feels exposing, so rehearse it in session. This is an adjunct to the client''s own support network and your clinical judgment.', '[{"id": "f0", "type": "textarea", "label": "The people I could call or text when an urge hits"}, {"id": "f1", "type": "textarea", "label": "What I want to say in the first sentence"}, {"id": "f2", "type": "textarea", "label": "What I want that person to do"}, {"id": "f3", "type": "textarea", "label": "What gets in the way of reaching out"}, {"id": "f4", "type": "textarea", "label": "A backup if no one answers"}]'::jsonb, array['addiction', 'support', 'urges']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('substance-use-cost-and-benefit-ledger', 'Substance Use Cost and Benefit Ledger', 'cbt'::resource_kind, 'A two-column ledger of what substance use gives and costs a client, kept in the client''s own words.', 'Help a client see the pull of substance use and its costs side by side without pressure.', array['Adults']::text[], '30 minutes', 'Invite the client to fill in what substance use does for them as honestly as what it costs; the benefit column is not a trap, and clients tend to engage more when it is respected. Revisit it over several sessions and note shifts. Let the client decide what to do with what they see.', '[{"id": "f0", "type": "textarea", "label": "What substance use gives me"}, {"id": "f1", "type": "textarea", "label": "What it costs me"}, {"id": "f2", "type": "textarea", "label": "What I would miss if I stopped"}, {"id": "f3", "type": "textarea", "label": "What I would gain if I changed"}, {"id": "f4", "type": "textarea", "label": "Which column surprised me"}, {"id": "f5", "type": "textarea", "label": "What I want to do with this"}]'::jsonb, array['addiction', 'decisions', 'pros and cons']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('choosing-over-craving-compass', 'Choosing Over Craving Compass', 'act'::resource_kind, 'An ACT compass pairing common urges with a value-guided action the client can pick instead.', 'Help a client act on a value while an urge is present instead of waiting for it to leave.', array['Adults']::text[], '25 minutes', 'Ask the client to name a value that matters to them, then link it with one action they can take in an urge moment. The point is willingness to carry the urge while doing something that matters, not suppressing it. Keep the actions small and concrete so they can be done in a hard moment.', '[{"id": "f0", "type": "textarea", "label": "A value that matters to me"}, {"id": "f1", "type": "textarea", "label": "The urge and how it shows up in my body"}, {"id": "f2", "type": "textarea", "label": "Thoughts that come with the urge"}, {"id": "f3", "type": "textarea", "label": "One action I can take that fits my value"}, {"id": "f4", "type": "textarea", "label": "Who or what could remind me of this"}, {"id": "f5", "type": "textarea", "label": "How it went when I tried it"}]'::jsonb, array['addiction', 'core ACT', 'values', 'urges']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('wave-skills-pocket-plan', 'Wave Skills Pocket Plan', 'dbt'::resource_kind, 'A pocket plan that sorts distress tolerance skills by how long an urge usually lasts and where the client is.', 'Give a client ready skills matched to the length and place of an urge.', array['Adults']::text[], '25 minutes', 'Work through the skills the client already knows, such as paced breathing, cold water or a brief walk, and place each by setting: home, work, public. Test one in session so it is real, then write the shortest version on a card. Update the plan after it has been used, and keep it flexible.', '[{"id": "f0", "type": "textarea", "label": "Places where urges show up for me"}, {"id": "f1", "type": "textarea", "label": "A skill I can use at home"}, {"id": "f2", "type": "textarea", "label": "A skill I can use at work or in public"}, {"id": "f3", "type": "textarea", "label": "How long the urge usually lasts"}, {"id": "f4", "type": "textarea", "label": "A skill I tried and how it went"}, {"id": "f5", "type": "textarea", "label": "What I will add to my card"}]'::jsonb, array['addiction', 'distress tolerance', 'urges', 'skills']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('roll-and-reflect-recovery-game', 'Roll and Reflect Recovery Game', 'game'::resource_kind, 'A dice game where each roll prompts a question about urges, support, routines and what a client is working toward.', 'Open conversation about substance use and change in a low-pressure way in a group.', array['Adults', 'Groups']::text[], '45 minutes', 'Players take turns rolling a die and answering the matching prompt from a list you prepare, with the right to pass on any turn. Set ground rules for respect and privacy at the start and keep sharing at the level people choose. Debrief by asking what each person heard that they might use this week.', '[{"id": "f0", "type": "textarea", "label": "Prompt one: a moment this week when I handled an urge"}, {"id": "f1", "type": "textarea", "label": "Prompt two: a person who supports me"}, {"id": "f2", "type": "textarea", "label": "Prompt three: a routine that helps me"}, {"id": "f3", "type": "textarea", "label": "Prompt four: a hard time of day and my plan"}, {"id": "f4", "type": "textarea", "label": "Prompt five: something I look forward to"}, {"id": "f5", "type": "textarea", "label": "Prompt six: something I want to try this week"}]'::jsonb, array['addiction', 'group', 'support']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('anger-trigger-timeline', 'Anger Trigger Timeline', 'worksheet'::resource_kind, 'A timeline of the hours before an angry moment to show where stress, tiredness and hurt built up.', 'Help a client see what built up before anger flared so they can step in earlier.', array['Adults', 'Teens']::text[], '30 minutes', 'Walk back with the client from one recent angry moment, hour by hour, noting hunger, sleep, stress, pain and small irritations. Many clients are surprised how much sits before the visible trigger. Keep it a map of patterns, not of blame, and choose one early point to try something different.', '[{"id": "f0", "type": "textarea", "label": "The angry moment I want to look at"}, {"id": "f1", "type": "textarea", "label": "What was happening an hour before"}, {"id": "f2", "type": "textarea", "label": "What was happening earlier that day"}, {"id": "f3", "type": "textarea", "label": "How my body felt"}, {"id": "f4", "type": "textarea", "label": "What hurt or worry sat underneath"}, {"id": "f5", "type": "textarea", "label": "The earliest point I could have done something different"}]'::jsonb, array['anger management', 'triggers', 'pattern']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('anger-pause-skills-card', 'Anger Pause Skills Card', 'dbt'::resource_kind, 'A card pairing a signal in the body with a DBT distress tolerance skill the client can use before reacting.', 'Give a client a body signal and a matching skill to use before an angry reaction.', array['Adults', 'Teens']::text[], '25 minutes', 'Have the client name their early body signals, such as heat, clenched jaw or fast breath, and match each to a skill such as paced breathing, cold water, or stepping out for a short walk. Practice one in session while mildly irritated. If safety toward anyone is a concern, use your own judgment and safety planning in session.', '[{"id": "f0", "type": "textarea", "label": "The first signals in my body that anger is rising"}, {"id": "f1", "type": "textarea", "label": "A skill I can use right then"}, {"id": "f2", "type": "textarea", "label": "A place I can go to cool down"}, {"id": "f3", "type": "textarea", "label": "What I will say to let people know I am pausing"}, {"id": "f4", "type": "textarea", "label": "How I will return to the conversation"}, {"id": "f5", "type": "textarea", "label": "What worked when I tried it"}]'::jsonb, array['anger management', 'distress tolerance', 'skills']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('anger-cycle-repair-conversation', 'Anger Cycle Repair Conversation', 'couples'::resource_kind, 'A guided conversation where each partner names their own anger cycle and one repair move after a heated moment.', 'Help partners each own their part of a heated pattern and plan a repair together.', array['Couples']::text[], '40 minutes', 'Each partner completes their own half: what they do when anger rises, what they need from the other, and what repair they can offer. Ensure it is safe for both to do this together; if either partner feels afraid of the other, use your clinical judgment before continuing. Have them swap and listen without rebuttal first.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I do when I get angry"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I do when I get angry"}, {"id": "f2", "type": "textarea", "label": "Partner A: what I need in that moment"}, {"id": "f3", "type": "textarea", "label": "Partner B: what I need in that moment"}, {"id": "f4", "type": "textarea", "label": "One repair move I can offer"}, {"id": "f5", "type": "textarea", "label": "What we agree to try next time"}]'::jsonb, array['anger management', 'couples', 'repair', 'relationship issues']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('feelings-behind-the-fire-drawing', 'Feelings Behind the Fire Drawing', 'kids'::resource_kind, 'A child draws a fire and the softer feelings, such as hurt or worry, that sit underneath it.', 'Help a child notice feelings under anger and share them with a parent.', array['Children']::text[], '25 minutes', 'The child draws a fire and then colors the feelings underneath: sad, worried, left out, tired. The parent listens and reflects what they see without correcting or fixing anything, then picks one thing to try next time. If a child discloses something worrying, remember your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "The fire I drew and when it showed up"}, {"id": "f1", "type": "textarea", "label": "A feeling hiding underneath the fire"}, {"id": "f2", "type": "textarea", "label": "A color I used for that feeling"}, {"id": "f3", "type": "textarea", "label": "What I want grown-ups to know"}, {"id": "f4", "type": "textarea", "label": "What my parent will do when they see my fire"}]'::jsonb, array['anger management', 'children', 'emotion identification']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('anger-reset-station-game', 'Anger Reset Station Game', 'game'::resource_kind, 'A turn-taking game where players pick station cards, such as breathe, stretch and count, and practice resets together.', 'Let a group practice calming moves while playing so the skills feel familiar.', array['Children', 'Teens', 'Groups']::text[], '30 minutes', 'Players take turns drawing a station card and acting it out for thirty seconds, while others copy or guess. Add a twist card that sets a mildly annoying scenario to reset from. Debrief by asking which reset felt easiest and which they might use at school or home. Keep it playful and let anyone pass.', '[{"id": "f0", "type": "textarea", "label": "The reset I tried today"}, {"id": "f1", "type": "textarea", "label": "What I noticed in my body after"}, {"id": "f2", "type": "textarea", "label": "Which reset I liked best"}, {"id": "f3", "type": "textarea", "label": "Where I could use it this week"}, {"id": "f4", "type": "textarea", "label": "What I will tell a friend about it"}]'::jsonb, array['anger management', 'play', 'regulation', 'group']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('urge-surfing-notes-for-compulsions', 'Urge Surfing Notes for Compulsions', 'worksheet'::resource_kind, 'A client tracks one urge to do a ritual as it rises, peaks and fades without acting on it.', 'Help a client notice that an urge to ritualize changes on its own over time.', array['Adults', 'Teens']::text[], '15 minutes', 'Use this when a client is ready to stay with one urge for a few minutes and watch what it does. Complete the first prompts together in session so the client knows what to write, then let them fill in the rest during or right after a practice at home. Pace it to what the client chooses, and keep your own judgment about which urge to start with.', '[{"id": "f0", "type": "textarea", "label": "The urge I noticed and where I was when it showed up"}, {"id": "f1", "type": "textarea", "label": "How strong the urge felt at the start, from 0 to 10"}, {"id": "f2", "type": "textarea", "label": "What my body felt like as the urge rose"}, {"id": "f3", "type": "textarea", "label": "What I did instead of the ritual while I waited"}, {"id": "f4", "type": "textarea", "label": "How strong the urge felt at the end, from 0 to 10"}, {"id": "f5", "type": "textarea", "label": "What I noticed about how the urge moved"}]'::jsonb, array['OCD', 'urges', 'practice']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('doubt-versus-evidence-columns', 'Doubt Versus Evidence Columns', 'cbt'::resource_kind, 'A two-column thought record that separates the what-if voice from what the client actually knows.', 'Help a client sort intrusive doubts from the facts in front of them.', array['Adults', 'Teens']::text[], '20 minutes', 'A familiar thought-record layout adapted for intrusive doubts. The client writes the doubt, then what they know for sure, then what remains uncertain. The aim is not to argue the doubt away or win certainty, but to see the two lists side by side. Notice if the exercise itself turns into a reassurance ritual and adjust as you see fit.', '[{"id": "f0", "type": "textarea", "label": "The doubt that showed up"}, {"id": "f1", "type": "textarea", "label": "How much I felt I had to act on it, from 0 to 10"}, {"id": "f2", "type": "textarea", "label": "What I actually know right now"}, {"id": "f3", "type": "textarea", "label": "What I cannot know for sure"}, {"id": "f4", "type": "textarea", "label": "What I could do that fits with living with that uncertainty"}, {"id": "f5", "type": "textarea", "label": "How I feel after seeing both lists"}]'::jsonb, array['OCD', 'thought record', 'uncertainty']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('values-over-rituals-compass', 'Values Over Rituals Compass', 'act'::resource_kind, 'A client names what matters most to them and compares it with where rituals pull their time.', 'Help a client connect one small step to a value rather than to relief from a ritual.', array['Adults', 'Teens']::text[], '25 minutes', 'This ACT-style values exercise lets a client name what they want their days to be about and look honestly at where rituals take time from it. Keep it curious and free of blame. Invite one small, chosen step toward a value, and be ready to revisit it next session, because the step belongs to the client and may need resizing.', '[{"id": "f0", "type": "textarea", "label": "Three things that matter most to me"}, {"id": "f1", "type": "textarea", "label": "A recent day when a ritual took time from one of them"}, {"id": "f2", "type": "textarea", "label": "What I wish I had spent that time on"}, {"id": "f3", "type": "textarea", "label": "One small step toward that value I could take this week"}, {"id": "f4", "type": "textarea", "label": "What might show up inside me when I take that step"}, {"id": "f5", "type": "textarea", "label": "What I would say to myself with kindness while I do it"}]'::jsonb, array['OCD', 'values', 'ACT']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('partner-role-in-rituals-agreement', 'Partner Role in Rituals Agreement', 'couples'::resource_kind, 'Both partners name how the partner joins in rituals and agree on kinder responses together.', 'Help partners agree on supportive responses that do not feed the ritual cycle.', array['Couples']::text[], '30 minutes', 'Each partner has a part here. The partner with the urges says what support actually helps, and the other partner says what they feel pulled to do when rituals start. Together they pick one response to try, such as a warm acknowledgment without reassurance. Slow, repeated rehearsal in session usually helps more than a long list, and the client sets the pace.', '[{"id": "f0", "type": "textarea", "label": "Partner with urges: a ritual where I ask my partner to help"}, {"id": "f1", "type": "textarea", "label": "Partner with urges: what support feels truly helpful to me"}, {"id": "f2", "type": "textarea", "label": "Other partner: what I usually do when this happens"}, {"id": "f3", "type": "textarea", "label": "Other partner: how it feels to do it"}, {"id": "f4", "type": "textarea", "label": "One warm response we agree to try this week"}, {"id": "f5", "type": "textarea", "label": "How we will check in with each other afterward"}]'::jsonb, array['OCD', 'partners', 'accommodation']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('boss-of-the-worry-brain-drawing', 'Boss of the Worry Brain Drawing', 'kids'::resource_kind, 'A child draws the worry brain as a character and practices talking back to it with a parent beside them.', 'Help a child separate themselves from the loud what-if voice that asks for rituals.', array['Children']::text[], '20 minutes', 'The child draws their worry brain as a character, gives it a name, and decides what it says. The parent sits close, says calmly that worry brain is not the boss, and does not answer its demands for reassurance. Let the child steer the drawing and the voice. If your child client discloses harm or abuse at any point, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "Draw my worry brain and give it a name"}, {"id": "f1", "type": "textarea", "label": "What my worry brain says to me"}, {"id": "f2", "type": "textarea", "label": "What my worry brain wants me to do"}, {"id": "f3", "type": "textarea", "label": "What I can say back to it"}, {"id": "f4", "type": "textarea", "label": "Who is the boss of me"}, {"id": "f5", "type": "textarea", "label": "What my parent will do to help me when worry brain gets loud"}]'::jsonb, array['OCD', 'children', 'drawing']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('rescue-plan-card-maker-for-panic', 'Rescue Plan Card Maker for Panic', 'dbt'::resource_kind, 'A client builds a small card of distress tolerance steps to read while panic is rising.', 'Help a client carry a short, personal list of steps for the first minutes of panic.', array['Adults', 'Teens']::text[], '20 minutes', 'A distress tolerance card the client writes in their own words and keeps in a wallet or phone. Choose steps they can actually do while their heart pounds, such as paced breathing out longer than in, cold water on the face, or naming five things they see. Rehearse reading the card aloud in session. Complete any prompt that touches on safety with the client yourself.', '[{"id": "f0", "type": "textarea", "label": "What panic feels like in my body at the very start"}, {"id": "f1", "type": "textarea", "label": "A step with cold or temperature that I will try"}, {"id": "f2", "type": "textarea", "label": "A breathing step in my own words"}, {"id": "f3", "type": "textarea", "label": "Five things I can see or touch right now"}, {"id": "f4", "type": "textarea", "label": "A kind sentence I will tell myself"}, {"id": "f5", "type": "textarea", "label": "Who I could text, and 988 if I ever feel unsafe, by call or text"}]'::jsonb, array['panic attacks', 'distress tolerance', 'skills']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('panic-mountain-drawing', 'Panic Mountain Drawing', 'kids'::resource_kind, 'A child draws a mountain that panic climbs and slides down, with a parent helping name each part.', 'Help a child see that panic rises, peaks and comes back down.', array['Children']::text[], '20 minutes', 'The child draws a mountain, marks where panic starts, where it feels biggest and where it slides down again. The parent sits with them and uses a calm, slow voice, naming sensations as they go without rushing the child. Practice breathing in and out like blowing on soup. Keep the pictures the child''s own. If your child client discloses harm or abuse at any point, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "Draw a mountain and put a flag where my panic starts"}, {"id": "f1", "type": "textarea", "label": "What my body feels like on the way up"}, {"id": "f2", "type": "textarea", "label": "What the very top feels like"}, {"id": "f3", "type": "textarea", "label": "What helps me slide back down"}, {"id": "f4", "type": "textarea", "label": "What my parent does to help me stay brave"}, {"id": "f5", "type": "textarea", "label": "A color I will use to show when I feel calm again"}]'::jsonb, array['panic attacks', 'children', 'drawing']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('name-the-sensation-card-game', 'Name the Sensation Card Game', 'game'::resource_kind, 'Players draw sensation cards and decide whether each one is panic, exercise or excitement.', 'Help clients see that many body sensations have more than one explanation.', array['Adults', 'Teens', 'Groups']::text[], '30 minutes', 'Make cards for sensations such as racing heart, dizziness, tight chest and sweaty hands. Players take turns drawing a card and naming three times a body might feel that way, only one of which is panic. The client scores a point for each reasonable idea. Close with a debrief, asking what it was like to see the same sensation in many settings.', '[{"id": "f0", "type": "textarea", "label": "The sensation I drew"}, {"id": "f1", "type": "textarea", "label": "Three times a body might feel this way"}, {"id": "f2", "type": "textarea", "label": "One time it might be panic"}, {"id": "f3", "type": "textarea", "label": "One time it might be exercise or excitement"}, {"id": "f4", "type": "textarea", "label": "What I noticed during the game"}, {"id": "f5", "type": "textarea", "label": "What I want to remember next time my heart races"}]'::jsonb, array['panic attacks', 'sensations', 'game']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('panic-aftermath-reflection-sheet', 'Panic Aftermath Reflection Sheet', 'worksheet'::resource_kind, 'A short sheet for the hour after a panic wave, noting what happened and what helped.', 'Help a client learn from a panic episode without replaying it or judging themselves.', array['Adults', 'Teens']::text[], '15 minutes', 'Have the client fill this in once the wave has passed rather than during it. It is meant to collect what actually helped, not to dissect every thought. If the client starts to ruminate, shorten the sheet and shift to what they can do next. Use it as a conversation starter in session, and decide with the client which ideas are worth repeating.', '[{"id": "f0", "type": "textarea", "label": "Where I was and what I was doing before it started"}, {"id": "f1", "type": "textarea", "label": "What I felt in my body first"}, {"id": "f2", "type": "textarea", "label": "What I did to get through it"}, {"id": "f3", "type": "textarea", "label": "How long it took to feel steadier, in my own words"}, {"id": "f4", "type": "textarea", "label": "What I would like to try next time"}, {"id": "f5", "type": "textarea", "label": "One kind thing I can say to myself now"}]'::jsonb, array['panic attacks', 'reflection', 'coping skills']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('safe-companion-plan-for-panic', 'Safe Companion Plan for Panic', 'couples'::resource_kind, 'Partners agree on what the supporter says and does, and what to leave out, when panic arrives.', 'Help partners respond to panic with calm presence instead of fixing or alarm.', array['Couples']::text[], '30 minutes', 'Both partners fill in their own prompts. The partner who feels panic names what helps and what does not, and the supporter names what they tend to do under stress. They agree on a short script and a signal, then rehearse it in session. Revisit the plan after a real episode and change whatever did not fit. Complete any safety prompt together in session.', '[{"id": "f0", "type": "textarea", "label": "Partner with panic: words that help me when it starts"}, {"id": "f1", "type": "textarea", "label": "Partner with panic: things that make it worse"}, {"id": "f2", "type": "textarea", "label": "Supporter: what I usually do when I get scared too"}, {"id": "f3", "type": "textarea", "label": "Supporter: a calm sentence I can say"}, {"id": "f4", "type": "textarea", "label": "Our signal that means panic is starting"}, {"id": "f5", "type": "textarea", "label": "Who we call, including 988 by call or text, if we are worried about safety"}]'::jsonb, array['panic attacks', 'partners', 'communication']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('pause-and-return-parent-skills-card', 'Pause and Return Parent Skills Card', 'dbt'::resource_kind, 'A parent practices stopping, steadying and coming back to a hard moment with their child.', 'Help a parent use distress tolerance skills before they respond to a child''s behavior.', array['Adults']::text[], '20 minutes', 'A DBT-style card for parents who feel their reactions speed up in a hard moment. The parent writes what a pause looks like for them, such as stepping back, slow breaths or cold water, and how they will return to their child. Rehearse it in session using a recent real moment. The focus is on steadying themselves, and you decide how much to explore beyond that.', '[{"id": "f0", "type": "textarea", "label": "A moment this week when I felt my reaction speed up"}, {"id": "f1", "type": "textarea", "label": "What I noticed in my body first"}, {"id": "f2", "type": "textarea", "label": "A skill I can use in ten seconds"}, {"id": "f3", "type": "textarea", "label": "What I will say to my child when I step away"}, {"id": "f4", "type": "textarea", "label": "How I will come back and reconnect"}, {"id": "f5", "type": "textarea", "label": "What I want to remember about being a parent when it is hard"}]'::jsonb, array['parenting', 'distress tolerance', 'skills']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('parent-values-letter', 'Parent Values Letter', 'act'::resource_kind, 'A parent writes a brief letter to their child about the kind of parent they want to be.', 'Help a parent act on their values in the small daily moments of parenting.', array['Adults']::text[], '25 minutes', 'The parent writes to their child, in their own words, about what they hope to stand for. It need not be shared. Use it to look at where daily stress pulls them away from those hopes, and to pick one small action that fits their values. Hold the exercise lightly and with kindness, since many parents arrive already harsh with themselves.', '[{"id": "f0", "type": "textarea", "label": "What I most want my child to know about me"}, {"id": "f1", "type": "textarea", "label": "What kind of parent I want to be"}, {"id": "f2", "type": "textarea", "label": "A recent moment when I acted like that parent"}, {"id": "f3", "type": "textarea", "label": "A moment when stress pulled me away from it"}, {"id": "f4", "type": "textarea", "label": "One small thing I can do this week to act on my values"}, {"id": "f5", "type": "textarea", "label": "What I would say to myself when I fall short"}]'::jsonb, array['parenting', 'values', 'ACT']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('bedtime-without-a-battle-game', 'Bedtime Without a Battle Game', 'game'::resource_kind, 'A parent and child take turns drawing steps cards to build a calm routine together.', 'Help a family build a predictable bedtime that the child helped design.', array['Children', 'Adults']::text[], '30 minutes', 'Players take turns drawing cards for bedtime steps, such as bath, pajamas, story and lights out, and place them in order on a path. The child may add or reorder one step, and the parent plays along rather than directing. Debrief at the end about which steps felt fun and which felt hard. Adapt the rules to the child''s age, and try the routine for a week before changing it.', '[{"id": "f0", "type": "textarea", "label": "The step I drew and where it goes on the path"}, {"id": "f1", "type": "textarea", "label": "A step I would like to add"}, {"id": "f2", "type": "textarea", "label": "A step that feels hard for me"}, {"id": "f3", "type": "textarea", "label": "What my parent will do to help with that step"}, {"id": "f4", "type": "textarea", "label": "How I want bedtime to feel"}, {"id": "f5", "type": "textarea", "label": "What we will try tonight"}]'::jsonb, array['parenting', 'routines', 'game']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('parent-thought-check-for-hard-moments', 'Parent Thought Check for Hard Moments', 'cbt'::resource_kind, 'A parent writes the thought that shows up when their child pushes back and tests whether it fits.', 'Help a parent notice the story behind their reaction and try a balanced alternative.', array['Adults']::text[], '20 minutes', 'A thought record shaped around a parenting moment. The parent notes the situation, the first thought, the feeling and what they did, then looks for a more balanced thought and tries it next time. Be careful that it does not become a way to blame themselves. Work from one recent, ordinary moment, and offer your own judgment on where to go further.', '[{"id": "f0", "type": "textarea", "label": "The moment with my child"}, {"id": "f1", "type": "textarea", "label": "The first thought that went through my mind"}, {"id": "f2", "type": "textarea", "label": "The feeling and how strong it was, from 0 to 10"}, {"id": "f3", "type": "textarea", "label": "What I did next"}, {"id": "f4", "type": "textarea", "label": "A more balanced way to see it"}, {"id": "f5", "type": "textarea", "label": "What I could try next time"}]'::jsonb, array['parenting', 'thought record', 'reactions']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('feelings-weather-chart-with-parent', 'Feelings Weather Chart with Parent', 'kids'::resource_kind, 'A child and parent draw a weather chart of feelings and use it to talk at the end of the day.', 'Help a child name feelings and help a parent respond with calm curiosity.', array['Children']::text[], '20 minutes', 'The child draws a weather picture for each feeling, such as stormy for angry or sunny for happy. The parent then asks which weather it was today, listens, and reflects back what they heard without fixing. Do it together in session first so the parent can see the pace. Parents can repeat it at bedtime. If your child client discloses harm or abuse at any point, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "Draw sunny weather for a happy feeling"}, {"id": "f1", "type": "textarea", "label": "Draw stormy weather for a hard feeling"}, {"id": "f2", "type": "textarea", "label": "Today my feeling weather was"}, {"id": "f3", "type": "textarea", "label": "What made the weather change"}, {"id": "f4", "type": "textarea", "label": "What my parent did that helped"}, {"id": "f5", "type": "textarea", "label": "What I want my parent to know about my weather"}]'::jsonb, array['parenting', 'children', 'feelings']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('good-enough-parent-standards-check', 'Good Enough Parent Standards Check', 'cbt'::resource_kind, 'Tests the rules a new parent holds about doing it right against what actually helps the baby.', 'Loosen rigid standards that feed guilt and exhaustion in the early months.', array['Adults']::text[], '20 minutes', 'Ask the client to list the shoulds they carry, then sort each one by what the baby needs versus what an imagined judge expects. Watch for standards borrowed from social media or family. Revisit one rule at a time and keep the new wording the client''s own.', '[{"id": "f0", "type": "textarea", "label": "A should I hold about being a parent (for example, I should never need help)"}, {"id": "f1", "type": "textarea", "label": "Where I learned that rule"}, {"id": "f2", "type": "textarea", "label": "What the baby actually needs in this situation"}, {"id": "f3", "type": "textarea", "label": "What I would tell a friend holding the same rule"}, {"id": "f4", "type": "textarea", "label": "A good enough version of the rule in my own words"}, {"id": "f5", "type": "textarea", "label": "One small thing I will do differently this week"}]'::jsonb, array['self-criticism', 'thinking traps', 'perinatal and postpartum']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('room-for-mixed-feelings-practice', 'Room for Mixed Feelings Practice', 'act'::resource_kind, 'Makes space for love, grief, relief and dread to sit side by side in the first months of parenting.', 'Help a new parent stop fighting mixed feelings and keep caring for the baby and themselves.', array['Adults']::text[], '25 minutes', 'Many new parents believe a difficult feeling means they are doing this wrong. Invite the client to name each feeling as present, without ranking them, and to notice which ones they push away. Keep the focus on the next caring action rather than on resolving the feelings.', '[{"id": "f0", "type": "textarea", "label": "Feelings I have had since the baby came, including the ones I am ashamed of"}, {"id": "f1", "type": "textarea", "label": "Which of them I try hardest to push away"}, {"id": "f2", "type": "textarea", "label": "What pushing it away costs me"}, {"id": "f3", "type": "textarea", "label": "How it feels in my body when I let it be there for a minute"}, {"id": "f4", "type": "textarea", "label": "What I care about that is still true while I feel this"}, {"id": "f5", "type": "textarea", "label": "One caring action I can take for the baby or me while the feeling stays"}]'::jsonb, array['acceptance', 'willingness', 'perinatal and postpartum']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('closeness-after-birth-pace-talk', 'Closeness After Birth Pace Talk', 'couples'::resource_kind, 'Gives both partners a structure for talking about physical and emotional closeness at a pace each can name.', 'Replace unspoken pressure and avoidance with an honest, paced conversation about closeness.', array['Couples']::text[], '30 minutes', 'Each partner completes their own side first, then shares in turn while the other reflects back without defending or negotiating. The partner who gave birth sets the pace on anything physical, and the other partner''s feelings of distance are named without blame. Stop before a decision is forced.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what closeness means to me right now"}, {"id": "f1", "type": "textarea", "label": "Partner A: what feels okay, and what I am not ready for"}, {"id": "f2", "type": "textarea", "label": "Partner A: what I miss and how I would like to say so"}, {"id": "f3", "type": "textarea", "label": "Partner B: what closeness means to me right now"}, {"id": "f4", "type": "textarea", "label": "Partner B: what I worry about when we do not talk about it"}, {"id": "f5", "type": "textarea", "label": "Partner B: how I can show care without pressure"}, {"id": "f6", "type": "textarea", "label": "Together: one small kind of closeness we both want this week"}]'::jsonb, array['communication', 'connection', 'perinatal and postpartum']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('welcome-home-big-sibling-craft', 'Welcome Home Big Sibling Craft', 'kids'::resource_kind, 'An older child decorates a welcome card and a helper badge to prepare for life with a new baby.', 'Give a child a concrete, positive role in the family during a big change.', array['Children']::text[], '20 minutes', 'The child draws the family including the baby and decorates a helper badge for jobs they choose. The parent sits alongside, names that big feelings about the baby are okay, and plans one short stretch of one-on-one time each day. Offer extra attention if jokes about sending the baby back appear. If a child discloses harm, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "Draw our family with the new baby in it"}, {"id": "f1", "type": "textarea", "label": "Draw or write three jobs I can do as a helper"}, {"id": "f2", "type": "textarea", "label": "Draw my face when I feel jealous or left out"}, {"id": "f3", "type": "textarea", "label": "One thing I would like to do just with a parent"}, {"id": "f4", "type": "textarea", "label": "What a parent says when I have a big feeling"}]'::jsonb, array['children', 'family', 'transition', 'perinatal and postpartum']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('sleep-deprived-skills-card', 'Sleep-Deprived Skills Card', 'dbt'::resource_kind, 'Pairs a short list of body-first and mind-first skills a parent can reach for in the worst sleep-deprived minutes.', 'Give an exhausted parent a few skills small enough to use mid-feed or mid-cry.', array['Adults']::text[], '20 minutes', 'Choose skills the client can do one-handed with a baby in their arms, such as cold water on the wrists, paced breathing, or a self-validating phrase. Rehearse them in session and have the client rate how intense things feel before and after. Keep the card small enough to photograph and keep on a phone.', '[{"id": "f0", "type": "textarea", "label": "The moments I feel closest to my limit"}, {"id": "f1", "type": "textarea", "label": "What my body does when I reach that point"}, {"id": "f2", "type": "textarea", "label": "Body skill I can use with a baby in my arms"}, {"id": "f3", "type": "textarea", "label": "A kind thing I can say to myself in that moment"}, {"id": "f4", "type": "textarea", "label": "Who I can text or call for a minute of relief"}, {"id": "f5", "type": "textarea", "label": "How strong the feeling was before (0 to 10) and after I tried a skill"}]'::jsonb, array['distress tolerance', 'skills', 'perinatal and postpartum']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('worth-prediction-experiment', 'Worth Prediction Experiment', 'cbt'::resource_kind, 'Turns a belief about being not enough into a prediction the client can test in daily life.', 'Check a self-critical prediction against what actually happens.', array['Adults', 'Teens']::text[], '20 minutes, then one week of testing', 'Pick one concrete situation where the client expects to be judged as lacking, such as speaking up in a meeting. Write the prediction and a rating of belief first, run the experiment, then compare. Expect the client to discount good outcomes, so ask what they would count as evidence beforehand.', '[{"id": "f0", "type": "textarea", "label": "The belief about myself I want to test"}, {"id": "f1", "type": "textarea", "label": "The situation where I can test it"}, {"id": "f2", "type": "textarea", "label": "What I predict will happen"}, {"id": "f3", "type": "textarea", "label": "How strongly I believe the prediction (0 to 100)"}, {"id": "f4", "type": "textarea", "label": "What actually happened"}, {"id": "f5", "type": "textarea", "label": "What I would conclude if a friend had had this outcome"}, {"id": "f6", "type": "textarea", "label": "How strongly I believe the original belief now (0 to 100)"}]'::jsonb, array['core beliefs', 'behavioral', 'self-esteem']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('two-truths-and-a-strength-game', 'Two Truths and a Strength Game', 'game'::resource_kind, 'A turn-taking game where players share two true facts and one strength they own, then take a challenge.', 'Practice naming a strength out loud and receiving a reaction without deflecting.', array['Groups', 'Teens']::text[], '20 minutes', 'Players take turns sharing two ordinary facts and one real strength, and the group guesses nothing; the speaker simply says it and the others respond with a thank you or a question. Set the rule that no one can cancel their own strength with a joke. Debrief on how it felt to say it and to hear it.', '[{"id": "f0", "type": "textarea", "label": "My two facts and my strength for this round"}, {"id": "f1", "type": "textarea", "label": "What I noticed in my body when I said the strength out loud"}, {"id": "f2", "type": "textarea", "label": "The moment I wanted to deflect, and what I did instead"}, {"id": "f3", "type": "textarea", "label": "A strength someone else named that I agreed with"}, {"id": "f4", "type": "textarea", "label": "One place I can name a strength this week"}]'::jsonb, array['group', 'play', 'self-esteem']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('imperfect-and-still-worthy-card', 'Imperfect and Still Worthy Card', 'dbt'::resource_kind, 'Applies radical acceptance to a flaw or mistake so a client can stop treating it as a verdict on their worth.', 'Hold a mistake with acceptance while still choosing what to repair or change.', array['Adults', 'Teens']::text[], '20 minutes', 'Choose one specific mistake or trait the client is fighting. Walk through accepting that it happened and that it has causes, without approving it, then pair it with a validation statement. Clients often hear acceptance as giving up, so keep naming the next effective step.', '[{"id": "f0", "type": "textarea", "label": "The mistake or flaw I keep fighting"}, {"id": "f1", "type": "textarea", "label": "What I tell myself it says about my worth"}, {"id": "f2", "type": "textarea", "label": "What I can accept is simply true (it happened, it had causes)"}, {"id": "f3", "type": "textarea", "label": "What I can still change or repair"}, {"id": "f4", "type": "textarea", "label": "A validating sentence I can say to myself"}, {"id": "f5", "type": "textarea", "label": "How I will notice when I slide back into fighting it"}]'::jsonb, array['acceptance', 'self-compassion', 'self-esteem']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('criticism-softening-swap', 'Criticism Softening Swap', 'couples'::resource_kind, 'Partners turn a harsh remark into a feeling and a request, so criticism stops landing on each other''s sense of worth.', 'Help partners speak needs without attacking character, and hear them without collapsing.', array['Couples']::text[], '30 minutes', 'Each partner picks a recent critical remark made or received and rewrites it as a feeling plus one request. The listening partner practices hearing it without proving they are good or bad. Notice who tends to shrink and who tends to sharpen. Slow things down and credit each attempt.', '[{"id": "f0", "type": "textarea", "label": "Partner A: a critical thing I said or heard recently"}, {"id": "f1", "type": "textarea", "label": "Partner A: the feeling and need underneath it"}, {"id": "f2", "type": "textarea", "label": "Partner A: my rewrite as a feeling plus a request"}, {"id": "f3", "type": "textarea", "label": "Partner B: a critical thing I said or heard recently"}, {"id": "f4", "type": "textarea", "label": "Partner B: the feeling and need underneath it"}, {"id": "f5", "type": "textarea", "label": "Partner B: my rewrite as a feeling plus a request"}, {"id": "f6", "type": "textarea", "label": "Together: what helps us hear a request without taking it as a verdict"}]'::jsonb, array['communication', 'Gottman', 'self-esteem']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('words-that-help-me-poster', 'Words That Help Me Poster', 'kids'::resource_kind, 'A child draws a poster of kind helper words to swap in when the mean voice in their head shows up.', 'Give a child a ready set of kinder things to say to themselves.', array['Children']::text[], '20 minutes', 'The child draws the mean voice as a silly character and then a helper voice with kind words in speech bubbles. The parent hangs the poster somewhere visible and says one helper phrase aloud when they hear the child put themselves down. Ask the parent to model self-talk on their own hard days. If a child discloses harm, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "Draw the mean voice as a silly character"}, {"id": "f1", "type": "textarea", "label": "Write or draw what it says to me"}, {"id": "f2", "type": "textarea", "label": "Draw the helper voice"}, {"id": "f3", "type": "textarea", "label": "Write three kind helper words I can say back"}, {"id": "f4", "type": "textarea", "label": "Where we will hang the poster"}, {"id": "f5", "type": "textarea", "label": "What my parent will say when they hear the mean voice"}]'::jsonb, array['children', 'self-talk', 'self-esteem']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('willing-to-be-seen-practice', 'Willing to Be Seen Practice', 'act'::resource_kind, 'Builds willingness to be noticed in small social moments while carrying nervous feelings along.', 'Choose social actions by what matters rather than by how nervous the body feels.', array['Adults', 'Teens']::text[], '25 minutes', 'Link one social action to a value such as friendship or learning, then rehearse making it while nervousness stays present. Ask the client to name what they are willing to feel instead of aiming for calm. Plan a small real-world action before the next session and review what showed up.', '[{"id": "f0", "type": "textarea", "label": "A person or place I would like to connect with, and why it matters"}, {"id": "f1", "type": "textarea", "label": "The nervous feelings and thoughts that show up around it"}, {"id": "f2", "type": "textarea", "label": "What I do to avoid being seen"}, {"id": "f3", "type": "textarea", "label": "What those escapes have cost me"}, {"id": "f4", "type": "textarea", "label": "What I am willing to feel to take one step"}, {"id": "f5", "type": "textarea", "label": "The step I will take, with a day and time"}]'::jsonb, array['values', 'willingness', 'social anxiety']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('awkward-moment-recovery-game', 'Awkward Moment Recovery Game', 'game'::resource_kind, 'Players draw awkward-moment cards and take turns playing out a calm recovery line in a mock social scene.', 'Practice recovering from a stumble in conversation so a slip feels survivable.', array['Groups', 'Teens']::text[], '25 minutes', 'Write awkward moments on cards, such as forgetting a name or saying something that lands oddly. Each player draws one, plays it with a partner, and tries a recovery line. The leader plays at the same level and is allowed to fumble. Debrief on how bad it really was and what the audience likely thought.', '[{"id": "f0", "type": "textarea", "label": "The awkward moment I drew"}, {"id": "f1", "type": "textarea", "label": "How bad I predicted it would feel (0 to 10)"}, {"id": "f2", "type": "textarea", "label": "The recovery line I used"}, {"id": "f3", "type": "textarea", "label": "How bad it actually felt (0 to 10)"}, {"id": "f4", "type": "textarea", "label": "What the other person likely noticed"}, {"id": "f5", "type": "textarea", "label": "A real moment I could recover from the same way"}]'::jsonb, array['group', 'play', 'social anxiety']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('opposite-action-for-social-withdrawal', 'Opposite Action for Social Withdrawal', 'dbt'::resource_kind, 'Walks a client through spotting the urge to withdraw from people and trying the opposite action in small steps.', 'Act opposite to the urge to avoid when avoiding does not fit the facts.', array['Adults', 'Teens']::text[], '25 minutes', 'Check first that the fear fits the facts of the situation; where it does not, plan an opposite action done fully, with posture, tone and eye contact matching. Start with the smallest version. Debrief the emotion after, not just the outcome, and note the urge fading.', '[{"id": "f0", "type": "textarea", "label": "The social situation I feel like skipping"}, {"id": "f1", "type": "textarea", "label": "The emotion and the urge it gives me"}, {"id": "f2", "type": "textarea", "label": "Does the fear fit the facts here? What are the facts?"}, {"id": "f3", "type": "textarea", "label": "The opposite action, in a small version"}, {"id": "f4", "type": "textarea", "label": "How I will do it fully (posture, voice, eye contact)"}, {"id": "f5", "type": "textarea", "label": "How the urge and the feeling changed afterward"}]'::jsonb, array['emotion regulation', 'skills', 'social anxiety']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('brave-hello-practice-cards', 'Brave Hello Practice Cards', 'kids'::resource_kind, 'A child decorates cards with small friendly actions and tries one at a time with a parent cheering nearby.', 'Build a child''s comfort with greetings and small social steps through play.', array['Children']::text[], '20 minutes, then daily', 'The child decorates cards such as saying hello, asking a name, or sharing a toy, and picks one to try each day. The parent practices the card at home first, then stays close without speaking for the child. Praise the try, not the result. If a child discloses harm, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "Draw my favorite brave hello card"}, {"id": "f1", "type": "textarea", "label": "Draw my face before I try it"}, {"id": "f2", "type": "textarea", "label": "Draw my face after I try it"}, {"id": "f3", "type": "textarea", "label": "Which card I will try first, and when"}, {"id": "f4", "type": "textarea", "label": "How a parent helps without doing it for me"}]'::jsonb, array['children', 'exposure', 'social anxiety']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('supporting-a-partner-before-social-events', 'Supporting a Partner Before Social Events', 'couples'::resource_kind, 'Partners agree how one can help the other face an event without rescuing or pushing.', 'Help partners plan social events together so support does not become avoidance or pressure.', array['Couples']::text[], '30 minutes', 'The anxious partner says what helps and what quietly keeps the fear going, such as answering for them or leaving early. The supporting partner shares what they worry about and what they can offer. Agree on a small plan and a signal, and note that staying for the whole event may be a stretch worth trying.', '[{"id": "f0", "type": "textarea", "label": "Partner A: the event, and what I fear will happen"}, {"id": "f1", "type": "textarea", "label": "Partner A: what helps me and what makes it harder in the long run"}, {"id": "f2", "type": "textarea", "label": "Partner A: the step I am willing to try"}, {"id": "f3", "type": "textarea", "label": "Partner B: what I worry about before these events"}, {"id": "f4", "type": "textarea", "label": "Partner B: how I can help without rescuing or pushing"}, {"id": "f5", "type": "textarea", "label": "Together: our signal and our plan for staying or leaving"}, {"id": "f6", "type": "textarea", "label": "Together: how we will talk about it afterward"}]'::jsonb, array['communication', 'support', 'social anxiety']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('firsts-without-them-planner', 'Firsts Without Them Planner', 'worksheet'::resource_kind, 'A client maps upcoming first holidays, birthdays and anniversaries after a loss and plans support for each.', 'Help a grieving client prepare for hard dates with choices, company and a gentle exit plan.', array['Adults', 'Teens']::text[], '25 minutes', 'Use this with a client facing a first season without someone who died. Go date by date and let the client decide what to keep, change or skip, since there is no right way to spend a hard day. Keep the plan flexible, and revisit it after the date to see what helped and what to adjust next time.', '[{"id": "f0", "type": "textarea", "label": "A date coming up that I am dreading"}, {"id": "f1", "type": "textarea", "label": "What I would like that day to look like"}, {"id": "f2", "type": "textarea", "label": "One tradition I want to keep, change or let rest"}, {"id": "f3", "type": "textarea", "label": "Who I would like near me, and who I will let know"}, {"id": "f4", "type": "textarea", "label": "A gentle way out if the day gets too heavy"}, {"id": "f5", "type": "textarea", "label": "One small thing I can do afterward to care for myself"}]'::jsonb, array['grief and loss', 'anniversaries', 'planning']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('should-have-thoughts-challenge-sheet', 'Should-Have Thoughts Challenge Sheet', 'cbt'::resource_kind, 'A client writes a should-have thought about a loss and weighs it against what was known at the time.', 'Soften self-blame after a loss by separating hindsight from what the client knew then.', array['Adults']::text[], '30 minutes', 'Many grieving clients replay what they should have done differently. This sheet uses a familiar thought-record structure to compare hindsight with the information and options the client actually had. Go slowly, and notice whether guilt is carrying love or pain that needs room. It is not meant to argue the client out of sorrow.', '[{"id": "f0", "type": "textarea", "label": "The should-have thought that keeps returning"}, {"id": "f1", "type": "textarea", "label": "How strongly I believe it right now, 0 to 10"}, {"id": "f2", "type": "textarea", "label": "What I knew at the time"}, {"id": "f3", "type": "textarea", "label": "What I did not know then and know now"}, {"id": "f4", "type": "textarea", "label": "What I would say to a friend who had this thought"}, {"id": "f5", "type": "textarea", "label": "A kinder, more balanced way to say it"}, {"id": "f6", "type": "textarea", "label": "How strongly I believe the original thought now, 0 to 10"}]'::jsonb, array['grief and loss', 'guilt', 'thought record']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('waves-of-grief-skills-card', 'Waves of Grief Skills Card', 'dbt'::resource_kind, 'A client builds a card pairing the strongest grief waves with one distress tolerance skill each.', 'Give a grieving client a few named skills for riding out waves of emotion without avoiding the loss.', array['Adults', 'Teens']::text[], '25 minutes', 'Grief tends to arrive in waves, and clients often feel they must either push it away or be swept under. Offer familiar distress tolerance skills such as paced breathing, temperature change or self-soothing with the senses, and let the client choose what fits. Rehearse one skill in session so it is familiar before a wave comes.', '[{"id": "f0", "type": "textarea", "label": "What a wave of grief feels like in my body"}, {"id": "f1", "type": "textarea", "label": "What usually sets a wave off"}, {"id": "f2", "type": "textarea", "label": "A skill I could try in the first minute of a wave"}, {"id": "f3", "type": "textarea", "label": "A way to soothe myself with my senses"}, {"id": "f4", "type": "textarea", "label": "Something that helps me ride it out and let it pass"}, {"id": "f5", "type": "textarea", "label": "Who I could reach out to afterward"}]'::jsonb, array['grief and loss', 'distress tolerance', 'skills']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('remembering-together-shoebox-craft', 'Remembering Together Shoebox Craft', 'kids'::resource_kind, 'A child decorates a shoebox and fills it with drawings and objects that remind them of someone who died.', 'Give a grieving child a hands-on way to keep memories and talk about the person.', array['Children']::text[], '40 minutes', 'The parent helps the child decorate a box and choose or draw things that remind them of the person, then listens as the child explains each one. Let the child lead and do not push for tears or words. The parent''s job is to stay close, answer questions simply and honestly, and say that all feelings are welcome. If a child discloses abuse or harm, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "A picture I drew of the person"}, {"id": "f1", "type": "textarea", "label": "Something we did together that I remember"}, {"id": "f2", "type": "textarea", "label": "Something that makes me think of them"}, {"id": "f3", "type": "textarea", "label": "A feeling I have today, and what color it is"}, {"id": "f4", "type": "textarea", "label": "Something I would like to ask or tell them"}, {"id": "f5", "type": "textarea", "label": "Who I can show my box to"}]'::jsonb, array['grief and loss', 'children', 'craft']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('grief-weather-charades-game', 'Grief Weather Charades Game', 'game'::resource_kind, 'Players act out and guess feelings that come with loss, then share one of their own in a safe, low-pressure round.', 'Help a family or group name the many feelings grief brings and show that others share them.', array['Children', 'Teens', 'Groups']::text[], '30 minutes', 'Write feelings that often come with loss, such as sad, angry, numb, relieved, guilty or lonely, on cards. Players take turns acting one out while others guess, and anyone may pass at any time. In the debrief, invite each person to share one feeling they have had lately and notice the ones that overlap. Keep the tone gentle and let people laugh and cry both.', '[{"id": "f0", "type": "textarea", "label": "A feeling I acted out or guessed"}, {"id": "f1", "type": "textarea", "label": "A feeling I did not expect to see on a card"}, {"id": "f2", "type": "textarea", "label": "One that I have felt this week"}, {"id": "f3", "type": "textarea", "label": "Something I learned about how other people grieve"}, {"id": "f4", "type": "textarea", "label": "One thing I would like someone to know about how I am doing"}]'::jsonb, array['grief and loss', 'feelings', 'family']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('support-in-the-hard-moments-map', 'Support in the Hard Moments Map', 'worksheet'::resource_kind, 'A client in a close relationship lists the moments that feel hardest and who or what can help in each one.', 'Help a client see where support is already available and where a gap needs attention.', array['Adults', 'Couples']::text[], '25 minutes', 'Use this when a client is struggling in a close relationship and feels alone with it. Have them name the recurring moments that are hardest, then list the people, activities and boundaries that help. The map can show where outside support is missing. Follow the client''s lead on whether to share parts of it with the partner.', '[{"id": "f0", "type": "textarea", "label": "The moment in this relationship that is hardest for me"}, {"id": "f1", "type": "textarea", "label": "What I usually do in that moment"}, {"id": "f2", "type": "textarea", "label": "What I wish I could do instead"}, {"id": "f3", "type": "textarea", "label": "Someone outside the relationship who could support me"}, {"id": "f4", "type": "textarea", "label": "One thing I will protect for myself this week"}, {"id": "f5", "type": "textarea", "label": "What I would like to bring to my next session"}]'::jsonb, array['relationship issues', 'support', 'boundaries']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('soft-start-up-rewrite-sheet', 'Soft Start-Up Rewrite Sheet', 'couples'::resource_kind, 'Each partner turns a harsh complaint into a soft start-up and names their own part and what they need.', 'Help both partners raise a concern gently, own their side and ask clearly for what they need.', array['Couples']::text[], '30 minutes', 'Partner A and Partner B each pick a recent complaint and rewrite it as a soft start-up: how I feel, about what, and what I would like. Each also names their own part in the pattern. Read the rewrites aloud in turn while the listener only reflects back what they heard. Step in if either partner slips into blame, and keep the tone curious rather than corrective.', '[{"id": "f0", "type": "textarea", "label": "Partner A: the complaint as I would usually say it"}, {"id": "f1", "type": "textarea", "label": "Partner A: my feeling, the situation and what I would like"}, {"id": "f2", "type": "textarea", "label": "Partner A: my part in how this tends to go"}, {"id": "f3", "type": "textarea", "label": "Partner B: the complaint as I would usually say it"}, {"id": "f4", "type": "textarea", "label": "Partner B: my feeling, the situation and what I would like"}, {"id": "f5", "type": "textarea", "label": "Partner B: my part in how this tends to go"}, {"id": "f6", "type": "textarea", "label": "What we each heard the other say"}]'::jsonb, array['relationship issues', 'communication', 'soft start-up']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('repair-after-a-fight-plan', 'Repair After a Fight Plan', 'couples'::resource_kind, 'Partners agree on how each will cool down, return to talk and repair after an argument.', 'Help both partners agree on a shared plan for repairing within a day of a fight.', array['Couples']::text[], '30 minutes', 'Walk both partners through what usually happens after a fight and what each wishes would happen. Each names how they cool down, what a good return to the conversation sounds like, and one gesture that signals care. Write the shared plan together and set a time to review it. Name each person''s part so the plan does not become one partner''s job.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I usually do after a fight"}, {"id": "f1", "type": "textarea", "label": "Partner A: what I need before I can talk again"}, {"id": "f2", "type": "textarea", "label": "Partner B: what I usually do after a fight"}, {"id": "f3", "type": "textarea", "label": "Partner B: what I need before I can talk again"}, {"id": "f4", "type": "textarea", "label": "How we will let each other know we are ready to return"}, {"id": "f5", "type": "textarea", "label": "One thing each of us will say or do to repair"}, {"id": "f6", "type": "textarea", "label": "When we will check in on how this plan is working"}]'::jsonb, array['relationship issues', 'repair', 'conflict']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('values-in-my-closest-relationships-compass', 'Values in My Closest Relationships Compass', 'act'::resource_kind, 'A client names the kind of partner, friend or family member they want to be and small actions that fit.', 'Link a client''s actions in a relationship to the values they choose rather than to old reactions.', array['Adults']::text[], '30 minutes', 'This is a values clarification exercise for a client whose reactions in a relationship pull them away from who they want to be. Have them name two or three values, notice where urges to withdraw, attack or please pull them away, and choose one small committed action. Review next session what happened and what got in the way.', '[{"id": "f0", "type": "textarea", "label": "The relationship I want to focus on"}, {"id": "f1", "type": "textarea", "label": "What matters most to me in it"}, {"id": "f2", "type": "textarea", "label": "What I tend to do when I feel hurt or threatened"}, {"id": "f3", "type": "textarea", "label": "How that reaction moves me away from what matters"}, {"id": "f4", "type": "textarea", "label": "One small action I could take this week that fits my values"}, {"id": "f5", "type": "textarea", "label": "A thought or feeling I will make room for while I do it"}]'::jsonb, array['relationship issues', 'values', 'committed action']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('listening-turns-card-game', 'Listening Turns Card Game', 'game'::resource_kind, 'Two or more players take turns answering prompt cards while others listen and reflect before replying.', 'Practice listening and reflecting in a low-stakes way before using it on harder topics.', array['Adults', 'Couples', 'Groups']::text[], '30 minutes', 'Prepare cards with light to medium prompts, such as a favorite memory together or something that made me feel understood this week. One player answers, and the listener reflects back what they heard before adding anything. Swap roles after each card. Debrief on what made it easier or harder to listen, and note anything the players want to try with real issues.', '[{"id": "f0", "type": "textarea", "label": "A prompt I answered and what I noticed"}, {"id": "f1", "type": "textarea", "label": "A time I felt really heard during the game"}, {"id": "f2", "type": "textarea", "label": "A time I wanted to jump in or fix"}, {"id": "f3", "type": "textarea", "label": "What helped me stay in the listening role"}, {"id": "f4", "type": "textarea", "label": "One way I want to listen differently this week"}]'::jsonb, array['relationship issues', 'listening', 'communication']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('stabilizing-pace-dial-sheet', 'Stabilizing Pace Dial Sheet', 'worksheet'::resource_kind, 'A client sets how much of any session topic feels workable and names signs to slow down or pause.', 'Give a survivor of sexual abuse control over pacing, with clear signals and agreed ways to pause.', array['Adults', 'Teens']::text[], '20 minutes', 'Use this at the start of work with a client who has experienced sexual abuse, and return to it often. The client sets their own pace and chooses signals for when to slow down or stop, and you agree on what you will do each time. Do not ask for any details of what happened. The aim is control and safety, and the client can change any answer at any time.', '[{"id": "f0", "type": "textarea", "label": "A sign in my body that tells me I need to slow down"}, {"id": "f1", "type": "textarea", "label": "A word or signal I can use to pause the session"}, {"id": "f2", "type": "textarea", "label": "What I would like my therapist to do when I use it"}, {"id": "f3", "type": "textarea", "label": "Something that helps me feel more present in the room"}, {"id": "f4", "type": "textarea", "label": "A topic I would like to leave alone for now"}, {"id": "f5", "type": "textarea", "label": "How I want to feel when I leave a session"}]'::jsonb, array['sexual abuse', 'safety', 'pacing']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('self-blame-compassion-reframe-sheet', 'Self-Blame Compassion Reframe Sheet', 'cbt'::resource_kind, 'A client notes a self-blaming thought and builds a kinder, more balanced response, without describing events.', 'Help a survivor of sexual abuse notice self-blame thoughts and respond with compassion and perspective.', array['Adults', 'Teens']::text[], '25 minutes', 'Self-blame and shame are common after abuse. This sheet works only with the thoughts that show up now, not with any account of what happened, so keep the client away from retelling. Notice the thought, rate how strongly it is believed, and build a response the client would offer a friend. Slow down if the client becomes overwhelmed and use a grounding step.', '[{"id": "f0", "type": "textarea", "label": "A self-blaming thought that shows up now"}, {"id": "f1", "type": "textarea", "label": "How strongly I believe it, 0 to 10"}, {"id": "f2", "type": "textarea", "label": "What I would say to a friend who thought this"}, {"id": "f3", "type": "textarea", "label": "A kinder and more balanced thought"}, {"id": "f4", "type": "textarea", "label": "How strongly I believe the original thought now, 0 to 10"}, {"id": "f5", "type": "textarea", "label": "Something I can do right now to be gentle with myself"}]'::jsonb, array['sexual abuse', 'self-blame', 'shame']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('safe-place-and-present-anchors-practice', 'Safe Place and Present Anchors Practice', 'dbt'::resource_kind, 'A client builds a safe place image and a set of five-senses anchors to use for grounding.', 'Give a survivor of sexual abuse reliable grounding skills to return to the present.', array['Adults', 'Teens']::text[], '25 minutes', 'Walk the client through choosing a calm place, real or imagined, and a short list of sensory anchors in the room. Practice in session until it works smoothly. Keep the focus on the present and do not ask for memories. If the client feels worse, shift to simply naming objects in the room and orienting to the day and time. If the client mentions thoughts of self-harm, go over 988 (call or text) together.', '[{"id": "f0", "type": "textarea", "label": "A place where I feel calm or safe"}, {"id": "f1", "type": "textarea", "label": "Something I can see right now that is gray, blue or green"}, {"id": "f2", "type": "textarea", "label": "A sound I can hear in this room"}, {"id": "f3", "type": "textarea", "label": "Something I can touch or feel under my hands"}, {"id": "f4", "type": "textarea", "label": "What I will tell myself to remember where and when I am"}, {"id": "f5", "type": "textarea", "label": "If I ever feel unsafe, I can call or text 988 or tell this person"}]'::jsonb, array['sexual abuse', 'grounding', 'stabilization']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('reclaiming-choices-values-sheet', 'Reclaiming Choices Values Sheet', 'act'::resource_kind, 'A client names areas of life where they want more choice and one small chosen action in each.', 'Help a survivor of sexual abuse notice their own values and make small chosen steps toward them.', array['Adults']::text[], '30 minutes', 'This exercise focuses on the present and on what the client chooses. Invite them to pick a life area, such as friendships, rest, work or creativity, and name what matters there. Then choose one small action entirely their own and note any thoughts or feelings that arrive. Do not ask for details of the past. Let the client set the pace and change the plan whenever they like.', '[{"id": "f0", "type": "textarea", "label": "A life area where I want more choice"}, {"id": "f1", "type": "textarea", "label": "What matters to me there"}, {"id": "f2", "type": "textarea", "label": "One small step I choose for this week"}, {"id": "f3", "type": "textarea", "label": "A thought or feeling that might show up as I try it"}, {"id": "f4", "type": "textarea", "label": "How I can make room for it and still take the step"}, {"id": "f5", "type": "textarea", "label": "Who I could tell about my step, if anyone"}]'::jsonb, array['sexual abuse', 'values', 'choice']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('my-body-is-my-own-safety-book', 'My Body Is My Own Safety Book', 'kids'::resource_kind, 'A child draws safe people, safe places and the words to use if something feels wrong or confusing.', 'Help a child learn that their body is their own and name trusted adults they can tell.', array['Children']::text[], '30 minutes', 'The parent sits beside the child, and together they draw safe adults, safe places and a plan for what to say if something feels off. Keep language simple and calm and do not question the child about any past events. The parent''s role is to listen, believe and stay calm. If a child discloses anything, follow your mandatory reporting duties and tell the parent what happens next.', '[{"id": "f0", "type": "textarea", "label": "A grown-up I trust and can draw here"}, {"id": "f1", "type": "textarea", "label": "A place where I feel safe"}, {"id": "f2", "type": "textarea", "label": "A rule I know about my body being my own"}, {"id": "f3", "type": "textarea", "label": "The words I can say if something feels wrong"}, {"id": "f4", "type": "textarea", "label": "The grown-up I will tell, and how"}]'::jsonb, array['sexual abuse', 'children', 'body safety']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('skill-pairing-before-the-storm-sheet', 'Skill Pairing Before the Storm Sheet', 'worksheet'::resource_kind, 'A sheet where a client pairs a calming skill with an early warning sign before distress peaks.', 'Help a client match the right skill to the earliest sign of rising distress.', array['Adults', 'Teens']::text[], '30 minutes', 'Walk through one recent hard moment and have your client find the first small sign, such as a clenched jaw or racing thoughts, then pick a skill sized for that stage. Clients often reach for big skills too late, so notice whether the match feels realistic. Keep it as a draft you revise together over a few weeks.', '[{"id": "f0", "type": "textarea", "label": "The first small sign I notice when things start to build"}, {"id": "f1", "type": "textarea", "label": "Where that sign shows up in my body or thoughts"}, {"id": "f2", "type": "textarea", "label": "A quick skill I could use right at that sign"}, {"id": "f3", "type": "textarea", "label": "A bigger skill for when distress is higher"}, {"id": "f4", "type": "textarea", "label": "What might get in the way of using them"}, {"id": "f5", "type": "textarea", "label": "One place I will keep a reminder of this pairing"}]'::jsonb, array['coping skills', 'early warning', 'planning']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('opposite-action-coping-check-in', 'Opposite Action Coping Check-In', 'dbt'::resource_kind, 'A DBT opposite action check-in for urges that come with a coping choice the client later questions.', 'Practice noticing an emotion''s urge and choosing an opposite action when it does not fit the facts.', array['Adults', 'Teens']::text[], '25 minutes', 'Opposite action works best when the client first names the emotion and checks whether it fits the situation. Use a recent example where the urge was to withdraw or shut down, then plan one small opposite step. Review how it felt in the next session rather than expecting it to feel natural at first.', '[{"id": "f0", "type": "textarea", "label": "The emotion I felt and what set it off"}, {"id": "f1", "type": "textarea", "label": "The urge that came with it"}, {"id": "f2", "type": "textarea", "label": "Does the emotion fit the facts? What do I notice?"}, {"id": "f3", "type": "textarea", "label": "The opposite action I could try, all the way"}, {"id": "f4", "type": "textarea", "label": "One small step I will take this week"}, {"id": "f5", "type": "textarea", "label": "How it went, and what I noticed afterward"}]'::jsonb, array['coping skills', 'opposite action', 'emotion regulation']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('coping-plan-for-two', 'Coping Plan for Two', 'couples'::resource_kind, 'Partners agree how each wants support during a hard moment and what each will do to help.', 'Help partners agree on how to support each other''s coping without taking it over.', array['Couples']::text[], '40 minutes', 'Each partner fills in their own side first, then you invite them to share and compare. Partner A names what helps and what does not when stressed; Partner B does the same, and then both name one thing they will offer. Watch for fixing or advice-giving and gently steer toward asking what the other wants.', '[{"id": "f0", "type": "textarea", "label": "Partner A: when I am stressed, what helps me most"}, {"id": "f1", "type": "textarea", "label": "Partner A: what does not help, even when meant kindly"}, {"id": "f2", "type": "textarea", "label": "Partner B: when I am stressed, what helps me most"}, {"id": "f3", "type": "textarea", "label": "Partner B: what does not help, even when meant kindly"}, {"id": "f4", "type": "textarea", "label": "What I will offer my partner when they are struggling"}, {"id": "f5", "type": "textarea", "label": "How we will ask each other what is needed"}, {"id": "f6", "type": "textarea", "label": "When we will check in on this plan"}]'::jsonb, array['coping skills', 'couples', 'communication']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('calm-corner-builder', 'Calm Corner Builder', 'kids'::resource_kind, 'A child designs and stocks a calm corner at home while a parent helps gather items.', 'Give a child a place and a few chosen tools to use when feelings run big.', array['Children']::text[], '30 minutes', 'The child draws the calm corner and picks what goes in it, such as a pillow, a drawing pad or a favorite stuffed animal. The parent helps gather the items and agrees to let the child go there without it being a punishment. Practice using it when the child is calm first. If a child discloses anything worrying while drawing, remember your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "Draw my calm corner and what goes in it"}, {"id": "f1", "type": "textarea", "label": "Three things I like in my calm corner"}, {"id": "f2", "type": "textarea", "label": "What my body feels like when I need to go there"}, {"id": "f3", "type": "textarea", "label": "How I want a grown-up to help me"}, {"id": "f4", "type": "textarea", "label": "What I will do first when I get there"}]'::jsonb, array['coping skills', 'children', 'regulation']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('coping-skill-charades', 'Coping Skill Charades', 'game'::resource_kind, 'A group game of acting out coping skills while others guess, followed by a debrief.', 'Make coping skills memorable and low pressure through play and shared discussion.', array['Groups', 'Teens']::text[], '30 minutes', 'Write skills on slips, such as stretching, counting breaths or calling a friend. Players take turns acting one out silently while the group guesses; the actor scores a point for each correct guess and the guesser gets one too. Close with the debrief prompts, and let people pass on any skill they do not want to act out.', '[{"id": "f0", "type": "textarea", "label": "The skill I acted out or guessed"}, {"id": "f1", "type": "textarea", "label": "A skill from the game I already use"}, {"id": "f2", "type": "textarea", "label": "A skill I want to try this week"}, {"id": "f3", "type": "textarea", "label": "When I might use it"}, {"id": "f4", "type": "textarea", "label": "What I liked about seeing others act them out"}]'::jsonb, array['coping skills', 'play', 'group']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('feared-thing-fact-and-feeling-sheet', 'Feared Thing Fact and Feeling Sheet', 'worksheet'::resource_kind, 'A sheet separating what a client knows about a feared thing from what the fear says will happen.', 'Help a client sort facts from fear-driven predictions before planning practice.', array['Adults', 'Teens']::text[], '30 minutes', 'Have your client name the feared thing and fill in both columns of facts and fears, then look at where they differ. Avoid arguing the fear away; the point is for the client to see the two voices side by side. Revisit after practice to see what changed, and adjust pacing to what your client can tolerate.', '[{"id": "f0", "type": "textarea", "label": "The thing or situation I fear"}, {"id": "f1", "type": "textarea", "label": "What I know about it for sure"}, {"id": "f2", "type": "textarea", "label": "What my fear tells me will happen"}, {"id": "f3", "type": "textarea", "label": "How strongly I believe the fear, 0 to 10"}, {"id": "f4", "type": "textarea", "label": "What I have avoided because of it"}, {"id": "f5", "type": "textarea", "label": "What I would like to be able to do instead"}]'::jsonb, array['phobias', 'thinking traps', 'psychoeducation']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('safety-behavior-spotting-log', 'Safety Behavior Spotting Log', 'cbt'::resource_kind, 'A log for catching small safety behaviors that quietly keep a fear going during exposure practice.', 'Help a client notice and gradually drop safety behaviors during practice.', array['Adults', 'Teens']::text[], 'One week', 'Safety behaviors such as always carrying a phone or standing near the door can feel harmless but may keep the fear alive. Ask your client to log them in ordinary situations and in practice, then choose one to drop at a time. Go slowly and use your judgment on which are reasonable to keep.', '[{"id": "f0", "type": "textarea", "label": "The situation I was in"}, {"id": "f1", "type": "textarea", "label": "The safety behavior I used"}, {"id": "f2", "type": "textarea", "label": "What I thought would happen without it"}, {"id": "f3", "type": "textarea", "label": "What actually happened"}, {"id": "f4", "type": "textarea", "label": "How anxious I felt, 0 to 10"}, {"id": "f5", "type": "textarea", "label": "One safety behavior I could try dropping next time"}]'::jsonb, array['phobias', 'exposure', 'safety behaviors']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('willing-to-feel-it-phobia-practice', 'Willing to Feel It Phobia Practice', 'act'::resource_kind, 'An ACT practice of making room for fear while taking one small step toward something that matters.', 'Help a client carry fear along while moving toward a valued action.', array['Adults', 'Teens']::text[], '30 minutes', 'Link a feared situation to something the client values, such as traveling to see family or going to a medical visit. Invite them to notice the fear as a visitor and pick a step they would take with it present. Watch for the step being used to push the fear away, and keep returning to the value.', '[{"id": "f0", "type": "textarea", "label": "Something that matters to me that my fear gets in the way of"}, {"id": "f1", "type": "textarea", "label": "The feared situation involved"}, {"id": "f2", "type": "textarea", "label": "The thoughts and feelings that show up"}, {"id": "f3", "type": "textarea", "label": "A way I can make room for them without fighting"}, {"id": "f4", "type": "textarea", "label": "One small step I am willing to take"}, {"id": "f5", "type": "textarea", "label": "What I will tell myself as I take it"}]'::jsonb, array['phobias', 'core ACT', 'values']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('fear-monster-costume-party', 'Fear Monster Costume Party', 'kids'::resource_kind, 'A child draws their fear as a silly monster and gives it a costume while a parent helps.', 'Help a child see a fear as something smaller and less powerful through drawing.', array['Children']::text[], '25 minutes', 'The child draws what scares them as a monster, then adds funny clothes or a silly name. The parent listens, does not tease, and asks what the monster says and what the child would like to say back. Use it as a warm-up before any gradual practice. If a child discloses something worrying, remember your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "Draw my fear as a monster"}, {"id": "f1", "type": "textarea", "label": "The silly costume I gave it"}, {"id": "f2", "type": "textarea", "label": "What the monster says to me"}, {"id": "f3", "type": "textarea", "label": "What I want to say back to it"}, {"id": "f4", "type": "textarea", "label": "One brave thing I could do this week"}, {"id": "f5", "type": "textarea", "label": "Who I want to cheer me on"}]'::jsonb, array['phobias', 'children', 'play']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('phobia-practice-dice-game', 'Phobia Practice Dice Game', 'game'::resource_kind, 'A table game where players roll for gentle practice cards and talk about what they notice.', 'Make brave practice feel playful and shared, with each person choosing their own pace.', array['Groups', 'Teens']::text[], '35 minutes', 'Make cards of small brave steps ranging from easy to harder, each tied to a number on a die. Players take turns rolling, may swap for an easier card, and either do the step or say how they would plan it. Everyone sets their own pace, and the debrief asks what surprised them. Do not push anyone toward a card they decline.', '[{"id": "f0", "type": "textarea", "label": "The card I drew and how I felt about it"}, {"id": "f1", "type": "textarea", "label": "What I did or how I would plan it"}, {"id": "f2", "type": "textarea", "label": "What happened to my fear while I did it"}, {"id": "f3", "type": "textarea", "label": "What surprised me"}, {"id": "f4", "type": "textarea", "label": "A step I want to try on my own"}]'::jsonb, array['phobias', 'play', 'group']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('appearance-thought-reframe-card', 'Appearance Thought Reframe Card', 'cbt'::resource_kind, 'A thought record for appearance-related thoughts, with a balanced response and a next step.', 'Help a client notice appearance thoughts and test them against what is actually happening.', array['Adults', 'Teens']::text[], '25 minutes', 'Use a recent moment when a client felt bad about how they looked. Walk through the thought, the feeling, the evidence on both sides and a more balanced thought. Many people find it easier to name the thinking trap than to argue with the thought. Keep practicing with ordinary examples before moving to harder ones.', '[{"id": "f0", "type": "textarea", "label": "The situation and what I felt"}, {"id": "f1", "type": "textarea", "label": "The thought about my appearance"}, {"id": "f2", "type": "textarea", "label": "A thinking trap it might be, such as mind reading"}, {"id": "f3", "type": "textarea", "label": "Evidence that fits and evidence that does not"}, {"id": "f4", "type": "textarea", "label": "A more balanced thought"}, {"id": "f5", "type": "textarea", "label": "What I will do next"}]'::jsonb, array['body image', 'core CBT', 'thinking traps']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('valued-day-without-the-mirror-voice', 'Valued Day Without the Mirror Voice', 'act'::resource_kind, 'An ACT exercise of choosing a valued action and carrying critical body thoughts along while doing it.', 'Help a client act on a value while appearance thoughts are present.', array['Adults', 'Teens']::text[], '30 minutes', 'Pick one activity your client has been holding back from, such as swimming, dancing or a social event, and connect it to a value. Invite them to name the critical voice and thank it for trying to help, then go anyway. Defusion phrases like ''I am having the thought that'' can help. Keep it voluntary and paced.', '[{"id": "f0", "type": "textarea", "label": "An activity I have been holding back from"}, {"id": "f1", "type": "textarea", "label": "The value behind it"}, {"id": "f2", "type": "textarea", "label": "The critical thoughts that show up"}, {"id": "f3", "type": "textarea", "label": "How I can name them without arguing"}, {"id": "f4", "type": "textarea", "label": "The step I will take with them along"}, {"id": "f5", "type": "textarea", "label": "What I noticed afterward"}]'::jsonb, array['body image', 'core ACT', 'defusion']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('self-soothing-after-a-hard-body-day', 'Self-Soothing After a Hard Body Day', 'dbt'::resource_kind, 'A DBT card pairing self-soothe and radical acceptance skills for days when body thoughts run loud.', 'Give a client a short plan of kind, grounded actions for hard body image moments.', array['Adults', 'Teens']::text[], '25 minutes', 'Build the card with the client by choosing one soothing action for each sense, plus a radical acceptance statement that fits them. Practice the plan when they are calm so it is ready on a hard day. Ask what else helps and keep checking whether any item turns into a way of avoiding feelings. If thoughts of self-harm arise, complete a safety conversation in session and share that 988 can be called or texted.', '[{"id": "f0", "type": "textarea", "label": "Something calming to see"}, {"id": "f1", "type": "textarea", "label": "Something calming to hear"}, {"id": "f2", "type": "textarea", "label": "Something calming to touch"}, {"id": "f3", "type": "textarea", "label": "A smell or taste that soothes me"}, {"id": "f4", "type": "textarea", "label": "An acceptance statement I can say to myself"}, {"id": "f5", "type": "textarea", "label": "Who I can reach out to, and 988 if I feel unsafe"}]'::jsonb, array['body image', 'distress tolerance', 'self-soothing']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('partner-compliments-that-land', 'Partner Compliments That Land', 'couples'::resource_kind, 'Partners share what kind of appreciation lands well and what feels uncomfortable about their bodies.', 'Help partners offer appreciation in ways that support rather than pressure body image.', array['Couples']::text[], '40 minutes', 'Each partner completes their own side privately, then you help them share. Partner A says which compliments feel good and which feel awkward; Partner B does the same, and each names one thing they will try. Watch for either partner taking a comment as criticism, and slow the pace to keep both feeling heard.', '[{"id": "f0", "type": "textarea", "label": "Partner A: a kind of appreciation that feels good to me"}, {"id": "f1", "type": "textarea", "label": "Partner A: a comment that feels uncomfortable"}, {"id": "f2", "type": "textarea", "label": "Partner B: a kind of appreciation that feels good to me"}, {"id": "f3", "type": "textarea", "label": "Partner B: a comment that feels uncomfortable"}, {"id": "f4", "type": "textarea", "label": "What I will try offering my partner"}, {"id": "f5", "type": "textarea", "label": "How we will tell each other when something misses"}]'::jsonb, array['body image', 'couples', 'communication']::text[], '2026-10-03T15:00:00+00:00'::timestamptz),
  ('superhero-body-power-poster', 'Superhero Body Power Poster', 'kids'::resource_kind, 'A child draws a poster of what their body can do, with a parent adding a power of their own.', 'Help a child build pride in what their body does and the people who love it.', array['Children']::text[], '25 minutes', 'The child draws themselves as a superhero and labels the body powers, such as strong legs for running or quick hands for building. The parent adds one power of their own and says what they appreciate in the child''s body doing. Keep comments on what bodies do. If a child shares something worrying, remember your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "My superhero name"}, {"id": "f1", "type": "textarea", "label": "Powers my body has"}, {"id": "f2", "type": "textarea", "label": "A power I want to practice"}, {"id": "f3", "type": "textarea", "label": "What my parent noticed my body can do"}, {"id": "f4", "type": "textarea", "label": "A power my parent has"}, {"id": "f5", "type": "textarea", "label": "Where we will hang our poster"}]'::jsonb, array['body image', 'children', 'play']::text[], '2026-10-03T15:00:00+00:00'::timestamptz)
